327:             $emailKey = hash('sha256', Str::lower(trim(is_string($email) ? $email : '')));
328: 
329:             return [
330:                 Limit::perMinute(5)->by('pos-login-email:'.$emailKey),
331:                 Limit::perHour(30)->by('pos-login-email-hour:'.$emailKey),
332:                 Limit::perMinute(120)->by('pos-login-ip:'.$networkIp($request)),
333:             ];
334:         });
335: 
336:         // حد الدخول الموحد: بالـ IP وبالمعرّف (بريد/هاتف) معًا
337:         RateLimiter::for('unified-login', function (Request $request) use ($networkIp) {
338:             // H2: طبّع المعرّف بنفس منطق CustomerAuthService::login، وإلا كانت
339:             // كل صيغة هاتف (‎+20/0020/مسافات/أرقام عربية) بعدّاد مستقل.
340:             // M3: المدخل قد يكون array فيصل قبل الـ validation — لا تصبه لـ string.
341:             $raw = $request->input('login');
342:             $normalized = ! is_string($raw) || trim($raw) === ''
343:                 ? 'invalid'
344:                 : (str_contains($raw, '@')
345:                     ? Str::lower(trim($raw))
346:                     : Customer::normalizePhone($raw));
347:             $id = hash('sha256', $normalized);
348: 
349:             return [
350:                 // M6: حد الـ IP قابل للضبط (شبكات CGNAT والفروع المشتركة)، وحد
351:                 // إبقاء حد ضيق لكل (IP + معرّف) ضد التخمين المركّز.
352:                 // الحدود العامة تحسب الفشل فقط داخل UnifiedAuthService.
353:                 Limit::perMinute((int) config('auth.unified_login_ip_minute', 120))->by('ip:'.$networkIp($request)),
354:                 Limit::perMinute(5)->by('id:'.$id.':'.$networkIp($request)),
355:             ];
356:         });
357: 
358:         RateLimiter::for('unified-handoff', fn (Request $request) => Limit::perMinute((int) config('auth.unified_handoff_ip_minute', 60))->by($networkIp($request)));
359:         RateLimiter::for('ai-chat', fn (Request $request) => Limit::perMinute(20)->by('ai-chat:'.($request->user('staff')?->id ?? $networkIp($request))));
360: 
361:         // M8: الـ handoff يعتمد على cache مشترك يدعم الأقفال عبر الخوادم.
362:         // file/array يكسرانه بصمت على عدة nodes — نبّه في الإنتاج مبكرًا.
363:         if ($this->app->environment('production')
364:             && ! in_array((string) config('cache.default'), ['redis', 'database', 'memcached', 'dynamodb'], true)) {
365:             throw new \LogicException('Staff handoff requires a shared lockable cache store in production. Use Redis or a shared database cache.');
366:         }
367:     }
