 23: final class AnalyzeProductPhotosTool implements AgentTool
 24: {
 25:     public function __construct(
 26:         private GeminiClient $gemini,
 27:         private EntityResolver $resolver,
 28:         private SettingService $settings,
 29:         private ProposalBuilder $proposals,
 30:         private CatalogPresenter $presenter,
 31:     ) {}
 32: 
 33:     public function name(): string
 34:     {
 35:         return 'analyze_product_photos';
 36:     }
 37: 
 38:     public function kind(): ToolKind
 39:     {
 40:         return ToolKind::Read;
 41:     }
 42: 
 43:     public function risk(): string
 44:     {
 45:         return 'low';
 46:     }
 47: 
