  5: namespace App\Services\Ai\Catalog\Tools;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Enums\SalesChannel;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\AiPendingAction;
 11: use App\Models\Category;
 12: use App\Models\ProductVariant;
 13: use App\Models\User;
 14: use App\Observers\CatalogRetailPriceObserver;
 15: use App\Services\Ai\Catalog\CatalogArgs;
 16: use App\Services\Ai\Catalog\CatalogPresenter;
 17: use App\Services\Ai\Contracts\LocksTargets;
 18: use App\Services\Ai\Contracts\UndoableTool;
 19: use App\Services\Ai\ProposalBuilder;
 20: use App\Services\Ai\ToolKind;
 21: use App\Services\Ai\ToolOutcome;
