 29: 
 30: final class BulkUpdatePricesTool implements LocksTargets, UndoableTool, WriteTool
 31: {
 32:     public function __construct(
 33:         private VariantService $variants,
 34:         private SettingService $settings,
 35:         private ProposalBuilder $proposals,
 36:         private CatalogPresenter $presenter,
 37:     ) {}
 38: 
 39:     public function name(): string
 40:     {
 41:         return 'bulk_update_prices';
 42:     }
 43: 
 44:     public function kind(): ToolKind
 45:     {
 46:         return ToolKind::Write;
 47:     }
 48: 
 49:     public function risk(): string
 50:     {
 51:         return 'high';
 52:     }
 53: 
 54:     public function permissions(): array
 55:     {
 56:         return ['products.update'];
 57:     }
 58: 
 59:     public function declaration(): array
 60:     {
 61:         return [
 62:             'name' => $this->name(),
 63:             'description' => 'تعديل جماعي لأسعار المتغيرات النشطة (نسبة مئوية / فرق ثابت / قيمة ثابتة) مع التقريب وحراس التسعير (عدم البيع بأقل من التكلفة وبقاء الجملة أقل من القطاعي).',
 64:             'parameters' => [
 65:                 'type' => 'OBJECT',
 66:                 'required' => ['scope', 'field', 'operation', 'value'],
 67:                 'properties' => (object) [
 68:                     'scope' => [
 69:                         'type' => 'OBJECT',
 70:                         'properties' => (object) [
 71:                             'category_id' => ['type' => 'INTEGER'],
 72:                             'include_children' => ['type' => 'BOOLEAN'],
 73:                             'product_ids' => ['type' => 'ARRAY', 'items' => ['type' => 'INTEGER']],
 74:                             'status' => ['type' => 'ARRAY', 'items' => ['type' => 'STRING', 'enum' => array_column(ProductStatus::cases(), 'value')]],
 75:                             'sales_channel' => ['type' => 'STRING', 'enum' => array_column(SalesChannel::cases(), 'value')],
 76:                         ],
 77:                     ],
 78:                     'field' => ['type' => 'STRING', 'enum' => ['retail_price', 'wholesale_price']],
 79:                     'operation' => ['type' => 'STRING', 'enum' => ['percent', 'fixed_delta', 'set']],
 80:                     'value' => ['type' => 'NUMBER'],
 81:                     'rounding' => ['type' => 'STRING', 'enum' => ['none', 'nearest_5', 'nearest_10', 'end_with_9', 'end_with_99']],
 82:                     'guard' => [
 83:                         'type' => 'OBJECT',
 84:                         'properties' => (object) [
 85:                             'never_below_cost' => ['type' => 'BOOLEAN'],
 86:                             'keep_wholesale_below_retail' => ['type' => 'BOOLEAN'],
 87:                         ],
 88:                     ],
 89:                 ],
 90:             ],
 91:         ];
 92:     }
 93: 
 94:     public function prepare(User $actor, array $args): ToolOutcome
 95:     {
 96:         $args = CatalogArgs::normalizeDigitsInArray($args);
 97:         $field = (string) ($args['field'] ?? 'retail_price');
 98:         if (! in_array($field, ['retail_price', 'wholesale_price'], true)) {
 99:             throw ValidationException::withMessages(['field' => ['الحقل لازم يكون retail_price أو wholesale_price.']]);
100:         }
101: 
102:         $operation = (string) ($args['operation'] ?? 'percent');
103:         if (! in_array($operation, ['percent', 'fixed_delta', 'set'], true)) {
104:             throw ValidationException::withMessages(['operation' => ['العملية لازم تكون percent أو fixed_delta أو set.']]);
105:         }
106: 
107:         if (! isset($args['value']) || ! is_numeric($args['value'])) {
108:             throw ValidationException::withMessages(['value' => ['قيمة التعديل مطلوبة.']]);
109:         }
110:         $value = (float) $args['value'];
111: 
112:         $rounding = (string) ($args['rounding'] ?? 'none');
113:         if (! in_array($rounding, ['none', 'nearest_5', 'nearest_10', 'end_with_9', 'end_with_99'], true)) {
114:             $rounding = 'none';
115:         }
116: 
117:         $guardCfg = is_array($args['guard'] ?? null) ? $args['guard'] : [];
118:         $neverBelowCost = ! array_key_exists('never_below_cost', $guardCfg) || (bool) $guardCfg['never_below_cost'];
119:         $keepWholesaleBelowRetail = ! array_key_exists('keep_wholesale_below_retail', $guardCfg) || (bool) $guardCfg['keep_wholesale_below_retail'];
120: 
121:         $scope = is_array($args['scope'] ?? null) ? $args['scope'] : [];
122:         $hasScopeFilter = ! empty($scope['category_id']) || ! empty($scope['product_ids']) || ! empty($scope['status']) || ! empty($scope['sales_channel']);
123:         if (! $hasScopeFilter) {
124:             throw ValidationException::withMessages(['scope' => ['لازم تحدد نطاق (قسم أو منتجات أو حالة) لتعديل الأسعار الجماعي.']]);
125:         }
126: 
127:         $query = ProductVariant::query()
128:             ->with('product:id,code,name_ar,category_id,status,sales_channel')
129:             ->where('product_variants.is_active', true)
130:             ->whereHas('product', function ($q) use ($scope): void {
131:                 if (! empty($scope['category_id'])) {
132:                     $cat = Category::find((int) $scope['category_id']);
133:                     if ($cat) {
134:                         $includeChildren = ! array_key_exists('include_children', $scope) || (bool) $scope['include_children'];
135:                         $ids = $includeChildren ? [$cat->id, ...$cat->descendantIds()] : [$cat->id];
136:                         $q->whereIn('category_id', $ids);
137:                     } else {
138:                         $q->where('category_id', (int) $scope['category_id']);
139:                     }
140:                 }
141:                 if (! empty($scope['product_ids']) && is_array($scope['product_ids'])) {
142:                     $q->whereIn('id', array_map('intval', $scope['product_ids']));
143:                 }
144:                 if (! empty($scope['status']) && is_array($scope['status'])) {
145:                     $q->whereIn('status', $scope['status']);
146:                 }
147:                 if (! empty($scope['sales_channel'])) {
148:                     $q->where('sales_channel', (string) $scope['sales_channel']);
149:                 }
150:             })
151:             ->orderBy('product_variants.id');
152: 
153:         $maxItems = max(1, (int) $this->settings->get('ai_catalog_bulk_price_max_items', 200));
154:         $totalMatching = (clone $query)->count();
155:         if ($totalMatching === 0) {
156:             throw ValidationException::withMessages(['scope' => ['مفيش متغيرات نشطة مطابقة للنطاق المحدد.']]);
157:         }
158:         if ($totalMatching > $maxItems) {
159:             throw ValidationException::withMessages([
160:                 'scope' => ["عدد المتغيرات المطابقة ({$totalMatching}) أكبر من الحد المسموح ({$maxItems}). ضيّق النطاق."],
161:             ]);
162:         }
163: 
164:         $variants = $query->get();
165:         $canViewCost = CostAccess::canView($actor);
166: 
167:         $rowsToApply = [];
168:         $uiAllRows = [];
169:         $blockedRows = [];
170:         $blockedByCostCount = 0;
171:         $expectedVersions = [];
172:         $inverse = [];
173:         $diffs = [];
174: 
175:         foreach ($variants as $v) {
176:             $oldPrice = $v->getAttribute($field) !== null ? (float) $v->getAttribute($field) : null;
177:             if ($oldPrice === null && $operation !== 'set') {
178:                 $blockedRows[] = [
179:                     'variant_id' => $v->id,
180:                     'sku' => $v->sku,
181:                     'product_code' => $v->product?->code,
182:                     'reason' => 'السعر الحالي فاضي؛ استخدم عملية set لتحديد سعر مبدئي.',
183:                 ];
184: 
185:                 continue;
186:             }
187: 
188:             $basePrice = $oldPrice ?? 0.0;
189:             $rawNew = match ($operation) {
190:                 'percent' => $basePrice * (1.0 + ($value / 100.0)),
191:                 'fixed_delta' => $basePrice + $value,
192:                 'set' => $value,
193:             };
194: 
195:             $newPrice = self::applyRounding($rawNew, $rounding);
196: 
197:             if ($newPrice <= 0) {
198:                 $blockedRows[] = [
199:                     'variant_id' => $v->id,
200:                     'sku' => $v->sku,
201:                     'product_code' => $v->product?->code,
202:                     'reason' => 'السعر الجديد لازم يكون أكبر من صفر.',
203:                 ];
204: 
205:                 continue;
206:             }
207: 
208:             // Guard 1: never_below_cost
209:             if ($neverBelowCost && $v->cost_price !== null && (float) $v->cost_price > 0 && $newPrice < (float) $v->cost_price) {
210:                 $blockedByCostCount++;
211:                 $blockedRows[] = [
212:                     'variant_id' => $v->id,
213:                     'sku' => $v->sku,
214:                     'product_code' => $v->product?->code,
215:                     'reason' => $canViewCost
216:                         ? 'السعر الجديد ('.$newPrice.') أقل من سعر التكلفة ('.(float) $v->cost_price.').'
217:                         : 'أسباب تسعير محمية',
218:                 ];
219: 
220:                 continue;
221:             }
222: 
223:             // Guard 2: keep_wholesale_below_retail
224:             if ($keepWholesaleBelowRetail) {
225:                 $effectiveRetail = $field === 'retail_price' ? $newPrice : ($v->retail_price !== null ? (float) $v->retail_price : null);
226:                 $effectiveWholesale = $field === 'wholesale_price' ? $newPrice : ($v->wholesale_price !== null ? (float) $v->wholesale_price : null);
227:                 if ($effectiveRetail !== null && $effectiveWholesale !== null && $effectiveWholesale >= $effectiveRetail) {
228:                     $blockedRows[] = [
229:                         'variant_id' => $v->id,
230:                         'sku' => $v->sku,
231:                         'product_code' => $v->product?->code,
232:                         'reason' => "سعر الجملة ({$effectiveWholesale}) هيبقى أكبر من أو يساوي القطاعي ({$effectiveRetail}).",
233:                     ];
234: 
235:                     continue;
236:                 }
237:             }
238: 
239:             $delta = $oldPrice !== null ? round($newPrice - $oldPrice, 2) : $newPrice;
240:             $pct = ($oldPrice !== null && $oldPrice > 0) ? round((($newPrice - $oldPrice) / $oldPrice) * 100, 2) : null;
241: 
242:             $rowsToApply[] = [
243:                 'id' => $v->id,
244:                 'old' => $oldPrice,
245:                 'new' => $newPrice,
246:                 'v' => (int) $v->lock_version,
247:             ];
248:             $expectedVersions['variant:'.$v->id] = (int) $v->lock_version;
249:             $inverse[(string) $v->id] = $oldPrice;
250:             $diffs[] = $delta;
251: 
252:             $uiAllRows[] = [
253:                 'variant_id' => $v->id,
254:                 'sku' => $v->sku,
255:                 'product_code' => $v->product?->code,
256:                 'product_name' => $v->product?->name_ar,
257:                 'old_price' => $oldPrice,
258:                 'new_price' => $newPrice,
259:                 'delta' => $delta,
260:                 'delta_pct' => $pct,
261:             ];
262:         }
263: 
264:         if ($rowsToApply === []) {
265:             $reasonMsg = $blockedByCostCount > 0 && ! $canViewCost
266:                 ? "{$blockedByCostCount} متغيرات اتستبعدت لأسباب تسعير محمية."
267:                 : 'كل المتغيرات المطابقة تم استبعادها بواسطة حراس التسعير.';
268:             throw ValidationException::withMessages(['value' => [$reasonMsg]]);
269:         }
270: 
271:         $topChanges = $uiAllRows;
272:         usort($topChanges, fn ($a, $b) => abs((float) $b['delta']) <=> abs((float) $a['delta']));
273:         $topChanges = array_slice($topChanges, 0, 10);
274: 
275:         $totalDelta = round(array_sum($diffs), 2);
276:         $avgDelta = count($diffs) > 0 ? round($totalDelta / count($diffs), 2) : 0.0;
277: 
278:         $summary = [
279:             'field' => $field,
280:             'operation' => $operation,
281:             'value' => $value,
282:             'rounding' => $rounding,
283:             'total_matched' => $totalMatching,
284:             'updated_count' => count($rowsToApply),
285:             'blocked_count' => count($blockedRows),
286:             'total_delta' => $totalDelta,
287:             'average_delta' => $avgDelta,
288:         ];
289: 
290:         $warnings = [];
291:         if ($blockedByCostCount > 0 && ! $canViewCost) {
292:             $warnings[] = "{$blockedByCostCount} متغيرات اتستبعدت لأسباب تسعير محمية";
293:         } elseif (count($blockedRows) > 0) {
