267:                     ->where('product_variants.cost_price', '>', 0)
268:                     ->whereNotNull('product_variants.retail_price')
269:                     ->whereColumn('product_variants.retail_price', '<=', 'product_variants.cost_price')
270:                     ->select('product_variants.*', 'products.code as product_code', 'products.name_ar as product_name_ar');
271:                 $belowCostCount = (clone $belowCostQuery)->count();
272:                 $belowCostExamples = (clone $belowCostQuery)
273:                     ->orderBy('product_variants.id')
274:                     ->limit(5)
275:                     ->get()
276:                     ->map(fn ($v) => [
277:                         'variant_id' => $v->id,
278:                         'sku' => $v->sku,
279:                         'product_id' => $v->product_id,
280:                         'product_code' => $v->product_code,
281:                         'anomaly' => 'retail_le_cost',
282:                         'retail_price' => (float) $v->retail_price,
283:                         'cost_price' => (float) $v->cost_price,
284:                         'deep_link' => '#/products/'.$v->product_id,
285:                     ])->all();
286:             }
287: 
288:             $totalAnomaliesCount = $wholesaleGeRetailCount + $belowCostCount;
289:             $anomalyExamples = array_slice(array_merge($wholesaleGeRetailExamples, $belowCostExamples), 0, 5);
290: 
291:             // 6. Empty categories (no products and no children)
292:             $emptyCategoriesQuery = Category::query()
293:                 ->whereDoesntHave('products')
294:                 ->whereDoesntHave('children');
295:             $emptyCategoriesCount = (clone $emptyCategoriesQuery)->count();
296:             $emptyCategoriesExamples = (clone $emptyCategoriesQuery)
297:                 ->orderBy('id')
298:                 ->limit(5)
299:                 ->get(['id', 'name_ar', 'slug', 'is_active'])
300:                 ->map(fn (Category $c) => [
301:                     'id' => $c->id,
302:                     'name_ar' => $this->presenter->untrusted($c->name_ar, 150),
303:                     'slug' => $c->slug,
304:                     'is_active' => (bool) $c->is_active,
305:                     'deep_link' => '#/categories?focus='.$c->id,
306:                 ])->all();
307: 
308:             // 7. Active categories under inactive parent
309:             $activeUnderInactiveCount = count($activeUnderInactiveParent);
310:             $activeUnderInactiveExamples = collect($activeUnderInactiveParent)
311:                 ->take(5)
312:                 ->map(fn (Category $c) => [
313:                     'id' => $c->id,
314:                     'parent_id' => $c->parent_id,
315:                     'name_ar' => $this->presenter->untrusted($c->name_ar, 150),
316:                     'slug' => $c->slug,
317:                     'deep_link' => '#/categories?focus='.$c->id,
318:                 ])->values()->all();
319: 
320:             // 8. Variants below reorder_level (if stock_levels exists)
321:             $lowStockCount = 0;
322:             $lowStockExamples = [];
323:             if (Schema::hasTable('stock_levels')) {
324:                 $lowStockQuery = StockLevel::query()
325:                     ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
326:                     ->join('products', 'products.id', '=', 'product_variants.product_id')
327:                     ->whereNull('product_variants.deleted_at')
328:                     ->whereNull('products.deleted_at')
329:                     ->where('product_variants.is_active', true)
330:                     ->where('stock_levels.reorder_level', '>', 0)
331:                     ->whereRaw('(stock_levels.on_hand - stock_levels.reserved - stock_levels.damaged) < stock_levels.reorder_level')
332:                     ->select(
333:                         'stock_levels.*',
334:                         'product_variants.sku',
335:                         'product_variants.product_id',
336:                         'products.code as product_code',
337:                         'products.name_ar as product_name_ar'
338:                     );
339:                 $lowStockCount = (clone $lowStockQuery)->count();
340:                 $lowStockExamples = (clone $lowStockQuery)
341:                     ->orderBy('stock_levels.id')
342:                     ->limit(5)
343:                     ->get()
344:                     ->map(fn ($s) => [
345:                         'variant_id' => (int) $s->product_variant_id,
346:                         'sku' => $s->sku,
347:                         'product_id' => (int) $s->product_id,
348:                         'product_code' => $s->product_code,
349:                         'available' => round((float) $s->on_hand - (float) $s->reserved - (float) $s->damaged, 2),
350:                         'reorder_level' => (float) $s->reorder_level,
351:                         'deep_link' => '#/products/'.$s->product_id,
352:                     ])->all();
353:             }
354: 
355:             $sections = [
356:                 'stale_drafts' => [
357:                     'count' => $staleDraftsCount,
358:                     'older_than_days' => $days,
359:                     'examples' => $staleDraftsExamples,
360:                 ],
361:                 'ready_drafts' => [
362:                     'count' => $readyDraftsCount,
363:                     'examples' => $readyDraftsExamples,
364:                 ],
365:                 'missing_images' => [
366:                     'count' => $missingImagesCount,
367:                     'examples' => $missingImagesExamples,
368:                 ],
369:                 'missing_prices' => [
370:                     'count' => $missingPricesCount,
371:                     'examples' => $missingPricesExamples,
372:                 ],
373:                 'price_anomalies' => [
374:                     'count' => $totalAnomaliesCount,
375:                     'wholesale_ge_retail_count' => $wholesaleGeRetailCount,
376:                     ...($canViewCost ? ['below_cost_count' => $belowCostCount] : []),
377:                     'examples' => $anomalyExamples,
378:                 ],
379:                 'empty_categories' => [
380:                     'count' => $emptyCategoriesCount,
381:                     'examples' => $emptyCategoriesExamples,
382:                 ],
383:                 'active_categories_under_inactive_parent' => [
384:                     'count' => $activeUnderInactiveCount,
385:                     'examples' => $activeUnderInactiveExamples,
386:                 ],
387:                 'low_stock_variants' => [
388:                     'count' => $lowStockCount,
389:                     'examples' => $lowStockExamples,
390:                 ],
391:             ];
392: 
393:             $checks = [
394:                 [
395:                     'key' => 'ready_drafts',
396:                     'ok' => $readyDraftsCount === 0,
397:                     'severity' => 'warning',
398:                     'label' => "مسودات جاهزة للنشر ({$readyDraftsCount})",
399:                     'message' => $readyDraftsCount > 0 ? "فيه {$readyDraftsCount} مسودة مستوفية كل الشروط وجاهزة للنشر." : 'مفيش مسودات معلقة جاهزة للنشر.',
400:                 ],
401:                 [
402:                     'key' => 'stale_drafts',
403:                     'ok' => $staleDraftsCount === 0,
404:                     'severity' => 'warning',
405:                     'label' => "مسودات أقدم من {$days} يوم ({$staleDraftsCount})",
406:                     'message' => $staleDraftsCount > 0 ? "فيه {$staleDraftsCount} مسودة بقالها أكتر من {$days} يوم." : 'مفيش مسودات قديمة متروكة.',
407:                 ],
408:                 [
409:                     'key' => 'missing_images',
410:                     'ok' => $missingImagesCount === 0,
411:                     'severity' => 'blocker',
412:                     'label' => "منتجات من غير صور ({$missingImagesCount})",
413:                     'message' => $missingImagesCount > 0 ? "فيه {$missingImagesCount} منتج من غير أي صورة." : 'كل المنتجات ليها صور.',
414:                 ],
415:                 [
416:                     'key' => 'missing_prices',
417:                     'ok' => $missingPricesCount === 0,
418:                     'severity' => 'blocker',
419:                     'label' => "متغيرات نشطة ناقصها أسعار ({$missingPricesCount})",
420:                     'message' => $missingPricesCount > 0 ? "فيه {$missingPricesCount} متغير نشط ناقصه السعر المطلوب." : 'كل المتغيرات النشطة مسعرة.',
421:                 ],
422:                 [
423:                     'key' => 'price_anomalies',
424:                     'ok' => $totalAnomaliesCount === 0,
425:                     'severity' => 'blocker',
426:                     'label' => "أسعار شاذة ({$totalAnomaliesCount})",
427:                     'message' => $totalAnomaliesCount > 0 ? "فيه {$totalAnomaliesCount} متغير بأسعار شاذة (الجملة >= القطاعي".($canViewCost ? ' أو القطاعي <= التكلفة' : '').').' : 'مفيش أسعار شاذة.',
428:                 ],
429:                 [
430:                     'key' => 'empty_categories',
431:                     'ok' => $emptyCategoriesCount === 0,
432:                     'severity' => 'warning',
433:                     'label' => "أقسام فاضية ({$emptyCategoriesCount})",
434:                     'message' => $emptyCategoriesCount > 0 ? "فيه {$emptyCategoriesCount} قسم من غير منتجات ولا أقسام فرعية." : 'مفيش أقسام فاضية.',
435:                 ],
436:                 [
437:                     'key' => 'active_categories_under_inactive_parent',
438:                     'ok' => $activeUnderInactiveCount === 0,
439:                     'severity' => 'blocker',
440:                     'label' => "أقسام نشطة تحت أب معطل ({$activeUnderInactiveCount})",
441:                     'message' => $activeUnderInactiveCount > 0 ? "فيه {$activeUnderInactiveCount} قسم نشط تحت قسم أب معطل." : 'كل مسارات الأقسام النشطة سليمة.',
442:                 ],
443:                 [
444:                     'key' => 'low_stock_variants',
445:                     'ok' => $lowStockCount === 0,
446:                     'severity' => 'warning',
447:                     'label' => "متغيرات تحت حد الطلب ({$lowStockCount})",
448:                     'message' => $lowStockCount > 0 ? "فيه {$lowStockCount} رصيد متغير تحت حد إعادة الطلب." : 'المخزون فوق حد إعادة الطلب.',
449:                 ],
450:             ];
451: 
452:             $nextActions = [];
453:             if ($readyDraftsCount > 0) {
454:                 $nextActions[] = [
455:                     'label' => 'خطط لإصلاح الكتالوج',
456:                     'prompt' => 'اعمل خطة إصلاح للكتالوج بناءً على التقرير',
457:                 ];
458:             }
459:             if ($missingImagesCount > 0) {
460:                 $nextActions[] = [
461:                     'label' => 'اعرض المنتجات اللي من غير صور',
462:                     'prompt' => 'وريني المنتجات اللي من غير صور',
463:                 ];
464:             }
465:             if ($missingPricesCount > 0) {
466:                 $nextActions[] = [
467:                     'label' => 'اعرض المنتجات اللي ناقصها أسعار',
468:                     'prompt' => 'وريني المنتجات اللي ناقصها أسعار',
469:                 ];
470:             }
471: 
472:             $hasIssues = collect($checks)->contains(fn ($c) => ! $c['ok']);
473: 
474:             return $this->presenter->present(
475:                 $actor,
476:                 $sections,
477:                 [
478:                     'type' => 'checklist',
479:                     'title' => 'تقرير صحة الكتالوج',
480:                     'verdict' => $hasIssues ? 'warning' : 'ready',
481:                     'checks' => $checks,
482:                     'next_actions' => $nextActions,
483:                 ],
484:             );
485:         });
486:     }
