 19: use App\Services\Ai\ToolKind;
 20: use App\Services\Ai\ToolOutcome;
 21: use App\Services\Ai\WriteTool;
 22: use App\Services\Catalog\CatalogLock;
 23: use App\Services\Catalog\ProductService;
 24: use App\Services\CostAccess;
 25: use App\Services\StaffAdministration;
 26: use Illuminate\Support\Str;
