 23: final class DeleteCategoryTool implements LocksTargets, WriteTool
 24: {
 25:     public function __construct(
 26:         private CategoryService $categories,
 27:         private ProposalBuilder $proposals,
 28:         private CatalogPresenter $presenter,
 29:     ) {}
 30: 
 31:     public function name(): string
 32:     {
 33:         return 'delete_category';
 34:     }
 35: 
 36:     public function kind(): ToolKind
 37:     {
 38:         return ToolKind::Write;
 39:     }
 40: 
 41:     public function risk(): string
 42:     {
 43:         return 'high';
 44:     }
 45: 
 46:     public function permissions(): array
 47:     {
 48:         return ['categories.delete'];
 49:     }
 50: 
 51:     public function declaration(): array
 52:     {
 53:         return [
 54:             'name' => $this->name(),
 55:             'description' => 'حذف قسم فاضي من الكتالوج (يرفض لو فيه أقسام فرعية أو منتجات).',
 56:             'parameters' => [
 57:                 'type' => 'OBJECT',
 58:                 'required' => ['category_id'],
 59:                 'properties' => (object) [
 60:                     'category_id' => ['type' => 'INTEGER'],
 61:                 ],
 62:             ],
 63:         ];
 64:     }
 65: 
 66:     public function prepare(User $actor, array $args): ToolOutcome
 67:     {
 68:         $args = CatalogArgs::normalizeDigitsInArray($args);
 69:         $category = Category::find((int) ($args['category_id'] ?? 0));
 70:         if (! $category) {
 71:             return ToolOutcome::denied('القسم مش موجود.', auditable: false);
 72:         }
 73: 
 74:         $childrenCount = $category->children()->count();
 75:         $productsCount = $category->products()->count();
 76: 
 77:         if ($childrenCount > 0 || $productsCount > 0) {
 78:             $reasons = [];
 79:             if ($childrenCount > 0) {
 80:                 $reasons[] = "{$childrenCount} قسم فرعي";
 81:             }
 82:             if ($productsCount > 0) {
 83:                 $reasons[] = "{$productsCount} منتج";
 84:             }
 85:             $joined = implode(' و ', $reasons);
 86: 
 87:             throw ValidationException::withMessages([
 88:                 'category_id' => ["ما ينفعش نحذف القسم «{$category->name_ar}» لأن تحته {$joined}. البديل: عطّل القسم بـ set_category_status أو انقل الأقسام الفرعية والمنتجات الأول."],
 89:             ]);
 90:         }
 91: 
 92:         return $this->proposals->make(
 93:             $actor,
 94:             $this->name(),
 95:             ['category_id' => $category->id],
 96:             risk: $this->risk(),
 97:             title: "حذف القسم: {$category->name_ar} ({$category->slug})",
 98:             before: [
 99:                 'id' => $category->id,
100:                 'name_ar' => $category->name_ar,
101:                 'name_en' => $category->name_en,
102:                 'slug' => $category->slug,
103:             ],
104:             after: null,
105:             warnings: ['الحذف هيشيل القسم؛ اتأكد إنه مش مطلوب.'],
106:             expectedVersions: ['category:'.$category->id => (int) $category->lock_version],
107:             typedConfirmation: $category->slug,
108:             typedConfirmationHint: 'اكتب slug القسم للتأكيد',
109:         );
110:     }
111: 
112:     public function lockTargets(AiPendingAction $action): void
113:     {
114:         CatalogLock::tree(shared: false);
115:     }
116: 
117:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
118:     {
119:         $category = Category::findOrFail((int) $action->args['category_id']);
120:         $expected = $action->expected_versions['category:'.$category->id] ?? null;
121:         if ($expected !== null && (int) $category->lock_version !== (int) $expected) {
122:             throw new BusinessException('القسم تعدّل في جلسة أخرى؛ أعد تحميل الصفحة وحاول مجددًا.', [], 409);
123:         }
124: 
125:         $name = $category->name_ar;
126:         $id = $category->id;
127:         $before = ['name_ar' => $category->name_ar, 'name_en' => $category->name_en, 'slug' => $category->slug];
128: 
129:         $this->categories->delete($category);
130: 
131:         StaffAdministration::audit(
132:             $actor,
133:             'category.deleted',
134:             'category',
135:             $id,
136:             ['id', 'slug'],
137:             $before,
138:             [],
139:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'category:'.$id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
140:         );
141: 
142:         return ToolOutcome::result(true, "اتحذف القسم «{$name}».", [
143:             'category_id' => $id,
144:             'deep_link' => '#/categories',
145:         ]);
146:     }
147: }  1: <?php
