 44:     {
 45:         return [
 46:             'name' => $this->name(),
 47:             'description' => 'بحث مباشر بالـ SKU أو الباركود أو كود المنتج (P00042): يرجع متغير واحد ومنتجه.',
 48:             'parameters' => [
 49:                 'type' => 'OBJECT',
 50:                 'required' => ['code'],
 51:                 'properties' => (object) [
 52:                     'code' => ['type' => 'STRING'],
 53:                 ],
 54:             ],
 55:         ];
