 58:     public function handle(User $actor, array $args): ToolOutcome
 59:     {
 60:         $args = CatalogArgs::normalizeDigitsInArray($args);
 61:         $code = trim((string) ($args['code'] ?? ''));
 62:         if ($code === '') {
 63:             return ToolOutcome::denied('الكود مطلوب.', auditable: false);
 64:         }
 65: 
 66:         $variant = $this->resolver->exactVariantByCode($code);
 67:         if ($variant) {
 68:             $product = Product::with(['category', 'variants.media', 'media'])->find($variant->product_id);
 69:             if (! $product) {
 70:                 return ToolOutcome::denied('المنتج المرتبط بالمتغير مش موجود.', auditable: false);
 71:             }
 72: 
 73:             return $this->presenter->present(
 74:                 $actor,
 75:                 [
 76:                     'matched_by' => 'variant',
 77:                     'variant' => $this->presenter->variant($variant, $actor),
 78:                     'product' => $this->presenter->product($product, $actor),
 79:                     'deep_link' => '#/products/'.$product->id,
 80:                 ],
 81:                 $this->presenter->productCardBlock($product, $actor)
 82:             );
 83:         }
 84: 
 85:         $product = Product::with(['category', 'variants.media', 'media'])
 86:             ->whereRaw('LOWER(code) = LOWER(?)', [$code])
 87:             ->first();
 88: 
 89:         if (! $product) {
 90:             return ToolOutcome::denied('مفيش منتج أو متغير بالكود أو الباركود ده.', auditable: false);
 91:         }
 92: 
 93:         $firstVariant = $product->variants->first();
 94: 
 95:         return $this->presenter->present(
 96:             $actor,
 97:             [
 98:                 'matched_by' => 'product_code',
 99:                 'variant' => $firstVariant ? $this->presenter->variant($firstVariant, $actor) : null,
100:                 'product' => $this->presenter->product($product, $actor),
101:                 'deep_link' => '#/products/'.$product->id,
102:             ],
103:             $this->presenter->productCardBlock($product, $actor)
104:         );
105:     }
