 25: final class SetVariantStatusTool implements LocksTargets, UndoableTool, WriteTool
 26: {
 27:     public function __construct(
 28:         private VariantService $variants,
 29:         private ProposalBuilder $proposals,
 30:         private CatalogPresenter $presenter,
 31:     ) {}
 32: 
 33:     public function name(): string
 34:     {
 35:         return 'set_variant_status';
 36:     }
 37: 
 38:     public function kind(): ToolKind
 39:     {
 40:         return ToolKind::Write;
 41:     }
 42: 
 43:     public function risk(): string
 44:     {
 45:         return 'medium';
 46:     }
 47: 
 48:     public function permissions(): array
 49:     {
 50:         return ['products.update'];
 51:     }
 52: 
 53:     public function declaration(): array
 54:     {
 55:         return [
 56:             'name' => $this->name(),
 57:             'description' => 'تفعيل أو تعطيل متغير منتج.',
 58:             'parameters' => [
 59:                 'type' => 'OBJECT',
 60:                 'required' => ['variant_id', 'is_active'],
 61:                 'properties' => (object) [
 62:                     'variant_id' => ['type' => 'INTEGER'],
 63:                     'is_active' => ['type' => 'BOOLEAN'],
 64:                 ],
 65:             ],
 66:         ];
 67:     }
 68: 
 69:     public function prepare(User $actor, array $args): ToolOutcome
 70:     {
 71:         $args = CatalogArgs::normalizeDigitsInArray($args);
 72:         $variant = ProductVariant::with('product')->find((int) ($args['variant_id'] ?? 0));
 73:         if (! $variant) {
 74:             return ToolOutcome::denied('المتغير مش موجود.', auditable: false);
 75:         }
 76: 
 77:         $targetActive = (bool) ($args['is_active'] ?? false);
 78:         if (! $targetActive && $variant->product && $variant->product->status === ProductStatus::Published) {
 79:             $hasOtherActive = $variant->product->variants()->where('is_active', true)->where('id', '!=', $variant->id)->exists();
 80:             if (! $hasOtherActive) {
 81:                 throw ValidationException::withMessages([
 82:                     'is_active' => ['لا يمكن تعطيل آخر متغير نشط في منتج منشور؛ أرشف المنتج أولًا.'],
 83:                 ]);
 84:             }
 85:         }
 86: 
 87:         $warnings = CatalogWarnings::forVariantChange($variant, ['is_active' => $targetActive]);
 88: 
 89:         return $this->proposals->make(
 90:             $actor,
 91:             $this->name(),
 92:             [
 93:                 'variant_id' => $variant->id,
 94:                 'is_active' => $targetActive,
 95:             ],
 96:             risk: $this->risk(),
 97:             title: ($targetActive ? 'تفعيل' : 'تعطيل')." المتغير {$variant->sku}",
 98:             before: ['is_active' => (bool) $variant->is_active],
 99:             after: ['is_active' => $targetActive],
100:             warnings: $warnings,
101:             expectedVersions: ['variant:'.$variant->id => (int) $variant->lock_version],
102:             inverse: ['is_active' => (bool) $variant->is_active],
103:         );
104:     }
105: 
106:     public function lockTargets(AiPendingAction $action): void
107:     {
108:         CatalogLock::tree(shared: true);
109:     }
110: 
111:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
112:     {
113:         $variant = ProductVariant::findOrFail((int) $action->args['variant_id']);
114:         $oldActive = (bool) $variant->is_active;
115:         $updated = $this->variants->update($variant, [
116:             'is_active' => (bool) $action->args['is_active'],
117:             'expected_version' => $action->expected_versions['variant:'.$variant->id] ?? null,
118:         ]);
119: 
120:         StaffAdministration::audit(
121:             $actor,
122:             'variant.status_changed',
123:             'variant',
124:             $updated->id,
125:             ['is_active'],
126:             ['is_active' => $oldActive],
127:             ['is_active' => (bool) $updated->is_active],
128:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'variant:'.$updated->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
129:         );
130: 
131:         return ToolOutcome::result(
132:             true,
133:             ($updated->is_active ? 'اتفعل' : 'اتعطل')." المتغير {$updated->sku}.",
134:             [
135:                 'variant_id' => $updated->id,
136:                 'sku' => $updated->sku,
137:                 'is_active' => (bool) $updated->is_active,
138:                 'deep_link' => "#/products/{$updated->product_id}",
139:             ]
140:         );
141:     }
142: 
143:     public function canUndo(AiPendingAction $action): bool
144:     {
145:         return is_array($action->inverse) && array_key_exists('is_active', $action->inverse);
146:     }
147: 
148:     public function targetState(AiPendingAction $action): string
149:     {
150:         $v = ProductVariant::findOrFail((int) $action->args['variant_id']);
151: 
152:         return hash('sha256', json_encode([$v->lock_version, (bool) $v->is_active], JSON_THROW_ON_ERROR));
153:     }
154: 
155:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
156:     {
157:         $variant = ProductVariant::findOrFail((int) $action->args['variant_id']);
158:         $updated = $this->variants->update($variant, [
159:             'is_active' => (bool) $action->inverse['is_active'],
160:         ]);
161: 
162:         return ToolOutcome::result(true, "تم التراجع عن تغيير حالة المتغير {$updated->sku}.", [
163:             'variant_id' => $updated->id,
164:             'deep_link' => "#/products/{$updated->product_id}",
165:         ]);
166:     }
167: }  1: <?php
