 76:         $category = Category::find((int) ($args['category_id'] ?? 0));
 77:         if (! $category) {
 78:             return ToolOutcome::denied('القسم مش موجود.', auditable: false);
 79:         }
 80: 
 81:         $input = Arr::only($args, ['name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order']);
 82:         $rules = Arr::only(UpdateCategoryRequest::baseRules($category->id), ['name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order']);
 83:         $data = CatalogArgs::validate($input, $rules);
 84: 
 85:         if ($data === []) {
