 87:         }
 88: 
 89:         $before = Arr::only($category->getAttributes(), array_keys($data));
 90:         $after = Arr::only($category->replicate()->fill($data)->getAttributes(), array_keys($data));
 91: 
 92:         return $this->proposals->make(
