114:         $data = Arr::except($action->args, ['category_id']) + [
115:             'expected_version' => $action->expected_versions['category:'.$category->id] ?? null,
116:         ];
117:         $updated = $this->categories->update($category, $data, null);
118: 
119:         StaffAdministration::audit(
120:             $actor,
