124:             array_keys(Arr::except($action->args, ['category_id'])),
125:             $before,
126:             Arr::only($updated->getAttributes(), array_keys($before)),
127:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'category:'.$updated->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
