 31:         'category_id',
 32:         'name_ar',
 33:         'name_en',
 34:         'slug',
 35:         'description_ar',
 36:         'description_en',
 37:         'material_ar',
 38:         'material_en',
 39:         'length_cm',
 40:         'width_cm',
 41:         'height_cm',
 42:         'weight_kg',
 43:         'warranty_months',
 44:         'warranty_details',
 45:         'country_of_origin',
