 50:         'badge_ar',
 51:     ];
 52: 
 53:     public function __construct(
 54:         private ProductService $products,
 55:         private ProductPublishabilityChecker $checker,
 56:         private ProposalBuilder $proposals,
 57:         private CatalogPresenter $presenter,
 58:     ) {}
 59: 
 60:     public function name(): string
 61:     {
 62:         return 'update_product';
