 81:     {
 82:         return [
 83:             'name' => $this->name(),
 84:             'description' => 'تعديل بيانات منتج (الاسم، الوصف، الخامة، القسم، الأبعاد، قناة البيع، المناسبات، الشارة). لتغيير الحالة استخدم set_product_status.',
 85:             'parameters' => [
 86:                 'type' => 'OBJECT',
 87:                 'required' => ['product_id'],
 88:                 'properties' => (object) [
 89:                     'product_id' => ['type' => 'INTEGER'],
 90:                     'category_id' => ['type' => 'INTEGER'],
 91:                     'name_ar' => ['type' => 'STRING'],
 92:                     'name_en' => ['type' => 'STRING'],
 93:                     'slug' => ['type' => 'STRING'],
 94:                     'description_ar' => ['type' => 'STRING'],
 95:                     'description_en' => ['type' => 'STRING'],
 96:                     'material_ar' => ['type' => 'STRING'],
 97:                     'material_en' => ['type' => 'STRING'],
 98:                     'length_cm' => ['type' => 'NUMBER'],
 99:                     'width_cm' => ['type' => 'NUMBER'],
100:                     'height_cm' => ['type' => 'NUMBER'],
101:                     'weight_kg' => ['type' => 'NUMBER'],
102:                     'warranty_months' => ['type' => 'INTEGER'],
103:                     'warranty_details' => ['type' => 'STRING'],
104:                     'country_of_origin' => ['type' => 'STRING'],
105:                     'sales_channel' => ['type' => 'STRING', 'enum' => array_column(SalesChannel::cases(), 'value')],
106:                     'is_featured' => ['type' => 'BOOLEAN'],
107:                     'occasions' => [
108:                         'type' => 'ARRAY',
109:                         'items' => ['type' => 'STRING', 'enum' => array_column(Occasion::cases(), 'value')],
110:                     ],
111:                     'badge_ar' => ['type' => 'STRING'],
112:                     'badge_en' => ['type' => 'STRING'],
113:                 ],
114:             ],
115:         ];
