118:     public function prepare(User $actor, array $args): ToolOutcome
119:     {
120:         $args = CatalogArgs::normalizeDigitsInArray($args);
121:         if (isset($args['dimensions']) && is_array($args['dimensions'])) {
122:             foreach (['length_cm', 'width_cm', 'height_cm', 'weight_kg'] as $dimKey) {
123:                 if (array_key_exists($dimKey, $args['dimensions']) && ! array_key_exists($dimKey, $args)) {
124:                     $args[$dimKey] = $args['dimensions'][$dimKey];
125:                 }
126:             }
127:         }
128: 
129:         $product = Product::with(['category', 'variants', 'media'])->find((int) ($args['product_id'] ?? 0));
130:         if (! $product) {
131:             return ToolOutcome::denied('المنتج مش موجود.', auditable: false);
132:         }
133: 
134:         $input = Arr::only($args, self::ALLOWED_FIELDS);
135:         $rules = Arr::only(UpdateProductRequest::baseRules($product->id), array_merge(self::ALLOWED_FIELDS, ['occasions.*']));
136:         $data = CatalogArgs::validate($input, $rules);
137: 
138:         if ($data === []) {
139:             return ToolOutcome::denied('مفيش حقول مطلوبة للتعديل.', auditable: false);
140:         }
141: 
142:         $warnings = CatalogWarnings::forProductChange($product, $data, $this->checker);
143: 
144:         $before = [];
145:         $after = [];
146:         $inverse = [];
147:         foreach (array_keys($data) as $field) {
148:             $oldVal = $product->getAttribute($field);
149:             if ($oldVal instanceof \BackedEnum) {
150:                 $oldVal = $oldVal->value;
151:             }
152:             $before[$field] = $oldVal;
153:             $after[$field] = $data[$field];
154:             $inverse[$field] = $oldVal;
155:         }
156: 
157:         return $this->proposals->make(
158:             $actor,
159:             $this->name(),
160:             $data + ['product_id' => $product->id],
161:             risk: $this->risk(),
162:             title: "تعديل المنتج {$product->code}: {$product->name_ar}",
163:             before: $before,
164:             after: $after,
165:             warnings: $warnings,
166:             expectedVersions: ['product:'.$product->id => (int) $product->lock_version],
167:             inverse: $inverse,
168:         );
169:     }
