172:     {
173:         CatalogLock::tree(shared: true);
174:     }
175: 
176:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
177:     {
178:         $product = Product::findOrFail((int) $action->args['product_id']);
179:         $fields = Arr::except($action->args, ['product_id']);
180:         $before = [];
