 26: final class UpdateVariantTool implements LocksTargets, UndoableTool, WriteTool
 27: {
 28:     public function __construct(
 29:         private VariantService $variants,
 30:         private ProposalBuilder $proposals,
 31:         private CatalogPresenter $presenter,
 32:     ) {}
 33: 
 34:     public function name(): string
 35:     {
 36:         return 'update_variant';
 37:     }
 38: 
 39:     public function kind(): ToolKind
 40:     {
 41:         return ToolKind::Write;
 42:     }
 43: 
 44:     public function risk(): string
 45:     {
 46:         return 'medium';
 47:     }
 48: 
 49:     public function permissions(): array
 50:     {
 51:         return ['products.update'];
 52:     }
 53: 
 54:     public function declaration(): array
 55:     {
 56:         return [
 57:             'name' => $this->name(),
 58:             'description' => 'تعديل متغير منتج واحد (سعر/لون/مقاس/باركود/حالة). للأسعار الجماعية استخدم bulk_update_prices.',
 59:             'parameters' => [
 60:                 'type' => 'OBJECT',
 61:                 'required' => ['variant_id'],
 62:                 'properties' => (object) [
 63:                     'variant_id' => ['type' => 'INTEGER'],
 64:                     'sku' => ['type' => 'STRING'],
 65:                     'barcode' => ['type' => 'STRING'],
 66:                     'retail_price' => ['type' => 'NUMBER'],
 67:                     'wholesale_price' => ['type' => 'NUMBER'],
 68:                     'compare_at_price' => ['type' => 'NUMBER'],
 69:                     'cost_price' => ['type' => 'NUMBER'],
 70:                     'color' => ['type' => 'STRING'],
 71:                     'size' => ['type' => 'STRING'],
 72:                     'capacity' => ['type' => 'STRING'],
 73:                     'reorder_level' => ['type' => 'INTEGER'],
 74:                     'weight_kg' => ['type' => 'NUMBER'],
 75:                     'is_active' => ['type' => 'BOOLEAN'],
 76:                 ],
 77:             ],
 78:         ];
 79:     }
 80: 
 81:     public function prepare(User $actor, array $args): ToolOutcome
 82:     {
 83:         $args = CatalogArgs::normalizeDigitsInArray($args);
 84:         $variant = ProductVariant::with('product')->find((int) ($args['variant_id'] ?? 0));
 85:         if (! $variant) {
 86:             return ToolOutcome::denied('المتغير مش موجود.', auditable: false);
 87:         }
 88: 
 89:         if (! CostAccess::canView($actor)) {
 90:             unset($args['cost_price']);
 91:         }
 92: 
 93:         $data = CatalogArgs::normalizeVariant($args);
 94:         CatalogArgs::validate($data, UpdateVariantRules::for($variant));
 95:         if ($data === []) {
 96:             return ToolOutcome::denied('مفيش حقول مطلوبة للتعديل.', auditable: false);
 97:         }
 98: 
 99:         $warnings = CatalogWarnings::forVariantChange($variant, $data);
100:         $inverse = Arr::only($variant->getAttributes(), array_keys($data));
101:         if (! CostAccess::canView($actor)) {
102:             unset($inverse['cost_price']);
103:         }
104: 
105:         return $this->proposals->make(
106:             $actor,
107:             $this->name(),
108:             $data + ['variant_id' => $variant->id],
109:             risk: $this->risk(),
110:             title: "تعديل {$variant->sku}",
111:             before: $this->presenter->variant($variant, $actor),
112:             after: $this->presenter->variant($variant->replicate()->fill($data), $actor),
113:             warnings: $warnings,
114:             expectedVersions: ['variant:'.$variant->id => (int) $variant->lock_version],
115:             inverse: $inverse,
116:         );
117:     }
118: 
119:     public function lockTargets(AiPendingAction $a): void
120:     {
121:         CatalogLock::tree(shared: true);
122:     }
123: 
124:     public function execute(User $actor, AiPendingAction $a): ToolOutcome
125:     {
126:         $variant = ProductVariant::findOrFail((int) $a->args['variant_id']);
127:         $fields = Arr::except($a->args, ['variant_id']);
128:         if (! CostAccess::canView($actor)) {
129:             unset($fields['cost_price']);
130:         }
131:         $before = Arr::only($variant->getAttributes(), array_keys($fields));
132:         $data = $fields + ['expected_version' => $a->expected_versions['variant:'.$variant->id] ?? null];
133:         $variant = $this->variants->update($variant, $data);
134: 
135:         StaffAdministration::audit(
136:             $actor,
137:             'variant.updated',
138:             'variant',
139:             $variant->id,
140:             array_keys($fields),
141:             $before,
142:             Arr::only($variant->getAttributes(), array_keys($fields)),
143:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'variant:'.$variant->id, 'conversation_id' => $a->conversation_id, 'action_id' => $a->id],
144:         );
145: 
146:         return ToolOutcome::result(true, 'اتعدل المتغير.', [
147:             'variant_id' => $variant->id,
148:             'sku' => $variant->sku,
149:             'deep_link' => "#/products/{$variant->product_id}",
150:         ]);
151:     }
152: 
153:     public function canUndo(AiPendingAction $a): bool
154:     {
155:         return $a->inverse !== null && $a->inverse !== [];
156:     }
157: 
158:     public function targetState(AiPendingAction $a): string
159:     {
160:         $v = ProductVariant::findOrFail((int) $a->args['variant_id']);
161: 
162:         return hash('sha256', json_encode([$v->lock_version, Arr::only($v->getAttributes(), array_keys($a->inverse))], JSON_THROW_ON_ERROR));
163:     }
164: 
165:     public function undo(User $actor, AiPendingAction $a): ToolOutcome
166:     {
167:         $variant = ProductVariant::findOrFail((int) $a->args['variant_id']);
168:         $variant = $this->variants->update($variant, (array) $a->inverse);
169: 
170:         return ToolOutcome::result(true, "تم التراجع عن تعديل المتغير {$variant->sku}.", [
171:             'variant_id' => $variant->id,
172:             'deep_link' => "#/products/{$variant->product_id}",
173:         ]);
174:     }
175: }  1: <?php
