  5: namespace App\Services\Ai\Catalog;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Models\Category;
  9: use App\Models\Product;
 10: use App\Models\ProductVariant;
 11: use App\Models\User;
 12: use App\Services\Ai\EntityResolver;
 13: use App\Services\Ai\ToolOutcome;
 14: use App\Services\Catalog\CategoryHierarchy;
 15: use App\Services\Catalog\ProductPublishabilityChecker;
 16: use App\Services\CostAccess;
 17: use App\Services\SettingService;
 18: use Illuminate\Support\Arr;
 19: use Illuminate\Support\Facades\Validator;
 20: use Illuminate\Validation\ValidationException;
 21: 
 22: final class CatalogPresenter
 23: {
 24:     public function __construct(
 25:         private SettingService $settings,
 26:         private ProductPublishabilityChecker $publishability,
 27:     ) {}
 28: 
 29:     /** @return array{untrusted_text: string} */
 30:     public function untrusted(?string $value, int $max = 300): array
 31:     {
 32:         $clean = mb_substr((string) preg_replace('/[\x00-\x1F\x7F]/u', ' ', (string) $value), 0, $max);
 33: 
 34:         return ['untrusted_text' => $clean];
 35:     }
 36: 
 37:     /**
 38:      * @param  array<string,mixed>  $data
 39:      * @param  array<string,mixed>|null  $uiBlock
 40:      */
 41:     public function present(User $actor, array $data, ?array $uiBlock = null, ?string $message = null): ToolOutcome
 42:     {
 43:         $canViewCost = CostAccess::canView($actor);
 44:         if (! $canViewCost) {
 45:             $data = $this->stripCost($data);
 46:             if ($uiBlock !== null) {
 47:                 $uiBlock = $this->stripCost($uiBlock);
 48:             }
 49:         }
 50: 
 51:         $maxChars = max(1024, (int) $this->settings->get('ai_tool_result_max_chars', 16000));
 52:         $encoded = json_encode($data, JSON_UNESCAPED_UNICODE);
 53:         if ($encoded !== false && strlen($encoded) > $maxChars) {
 54:             return ToolOutcome::data([
 55:                 'truncated' => true,
 56:                 'message' => 'ضيّق البحث',
 57:             ], $uiBlock, 'ضيّق البحث');
 58:         }
 59: 
 60:         return ToolOutcome::data($data, $uiBlock, $message);
 61:     }
 62: 
 63:     /** @return array<string,mixed> */
 64:     public function stripCost(array $payload): array
 65:     {
 66:         $out = [];
 67:         foreach ($payload as $key => $value) {
 68:             if ($key === 'cost_price' || $key === 'cost') {
 69:                 continue;
 70:             }
 71:             $out[$key] = is_array($value) ? $this->stripCost($value) : $value;
 72:         }
 73: 
 74:         return $out;
 75:     }
 76: 
 77:     /** @return array<string,mixed> */
 78:     public function category(Category $category, ?User $actor = null): array
 79:     {
 80:         return [
 81:             'id' => $category->id,
 82:             'parent_id' => $category->parent_id,
 83:             'name_ar' => $this->untrusted($category->name_ar, 150),
 84:             'name_en' => $this->untrusted($category->name_en, 150),
 85:             'slug' => $category->slug,
 86:             'description_ar' => $category->description_ar !== null ? $this->untrusted($category->description_ar, 300) : null,
 87:             'description_en' => $category->description_en !== null ? $this->untrusted($category->description_en, 300) : null,
 88:             'sort_order' => (int) $category->sort_order,
 89:             'is_active' => (bool) $category->is_active,
 90:             'active_path' => CategoryHierarchy::activePath($category),
 91:             'deep_link' => '#/categories?focus='.$category->id,
 92:         ];
 93:     }
 94: 
 95:     /** @return array<string,mixed> */
 96:     public function product(Product $product, User $actor): array
 97:     {
 98:         $product->loadMissing(['category', 'variants', 'media']);
 99:         $canViewCost = CostAccess::canView($actor);
100:         $variants = $product->variants->map(fn (ProductVariant $v) => $this->variant($v, $actor))->values()->all();
101:         $activeVariants = $product->variants->where('is_active', true);
102:         $retailPrices = $activeVariants->pluck('retail_price')->filter(fn ($p) => $p !== null && $p > 0)->map(fn ($p) => (float) $p);
103:         $wholesalePrices = $activeVariants->pluck('wholesale_price')->filter(fn ($p) => $p !== null && $p > 0)->map(fn ($p) => (float) $p);
104: 
105:         $imagesCount = $product->media->where('collection_name', 'images')->count()
106:             + $product->variants->sum(fn (ProductVariant $v) => $v->relationLoaded('media') ? $v->media->where('collection_name', 'images')->count() : $v->media()->where('collection_name', 'images')->count());
107: 
108:         $checks = $this->publishability->evaluate($product);
109:         $ready = ! collect($checks)->contains(fn ($c) => ! $c['ok']);
110: 
111:         $out = [
112:             'id' => $product->id,
113:             'code' => $product->code,
114:             'category_id' => $product->category_id,
115:             'category_name' => $product->category ? $this->untrusted($product->category->name_ar, 150) : null,
116:             'name_ar' => $this->untrusted($product->name_ar, 255),
117:             'name_en' => $this->untrusted($product->name_en, 255),
118:             'slug' => $product->slug,
119:             'description_ar' => $product->description_ar !== null ? $this->untrusted($product->description_ar, 300) : null,
120:             'description_en' => $product->description_en !== null ? $this->untrusted($product->description_en, 300) : null,
121:             'material_ar' => $product->material_ar !== null ? $this->untrusted($product->material_ar, 150) : null,
122:             'material_en' => $product->material_en !== null ? $this->untrusted($product->material_en, 150) : null,
123:             'status' => $product->status instanceof ProductStatus ? $product->status->value : (string) $product->status,
124:             'sales_channel' => $product->sales_channel instanceof \BackedEnum ? $product->sales_channel->value : (string) $product->sales_channel,
125:             'is_featured' => (bool) $product->is_featured,
126:             'occasions' => $product->occasions ?? [],
127:             'badge_ar' => $product->badge_ar,
128:             'badge_en' => $product->badge_en,
129:             'dimensions' => [
130:                 'length_cm' => $product->length_cm !== null ? (float) $product->length_cm : null,
131:                 'width_cm' => $product->width_cm !== null ? (float) $product->width_cm : null,
132:                 'height_cm' => $product->height_cm !== null ? (float) $product->height_cm : null,
133:                 'weight_kg' => $product->weight_kg !== null ? (float) $product->weight_kg : null,
134:             ],
135:             'price_range' => [
136:                 'min_retail' => $retailPrices->isNotEmpty() ? $retailPrices->min() : null,
137:                 'max_retail' => $retailPrices->isNotEmpty() ? $retailPrices->max() : null,
138:                 'min_wholesale' => $wholesalePrices->isNotEmpty() ? $wholesalePrices->min() : null,
139:                 'max_wholesale' => $wholesalePrices->isNotEmpty() ? $wholesalePrices->max() : null,
140:             ],
141:             'images_count' => $imagesCount,
142:             'variants_count' => count($variants),
143:             'variants' => $variants,
144:             'publishability' => [
145:                 'ready' => $ready,
146:                 'checks' => $checks,
147:             ],
148:             'deep_link' => '#/products/'.$product->id,
149:         ];
150: 
151:         return $canViewCost ? $out : $this->stripCost($out);
152:     }
153: 
154:     /** @return array<string,mixed> */
155:     public function productCardBlock(Product $product, User $actor): array
156:     {
157:         $product->loadMissing(['category', 'variants.media', 'media']);
158:         $activeVariants = $product->variants->where('is_active', true);
159:         $retailPrices = $activeVariants->pluck('retail_price')->filter(fn ($p) => $p !== null && $p > 0)->map(fn ($p) => (float) $p);
160:         $wholesalePrices = $activeVariants->pluck('wholesale_price')->filter(fn ($p) => $p !== null && $p > 0)->map(fn ($p) => (float) $p);
161:         $cover = $product->media->where('collection_name', 'images')->sortBy('order_column')->first()
162:             ?? $product->variants->flatMap(fn ($v) => $v->media->where('collection_name', 'images'))->sortBy('order_column')->first();
163:         $checks = $this->publishability->evaluate($product);
164: 
165:         return [
166:             'type' => 'product_card',
167:             'id' => $product->id,
168:             'code' => $product->code,
169:             'name_ar' => $product->name_ar,
170:             'name_en' => $product->name_en,
171:             'status' => $product->status instanceof ProductStatus ? $product->status->value : (string) $product->status,
172:             'sales_channel' => $product->sales_channel instanceof \BackedEnum ? $product->sales_channel->value : (string) $product->sales_channel,
173:             'category_name' => $product->category?->name_ar,
174:             'thumb_url' => $cover ? $cover->getUrl() : null,
175:             'price_range' => [
176:                 'min_retail' => $retailPrices->isNotEmpty() ? $retailPrices->min() : null,
177:                 'max_retail' => $retailPrices->isNotEmpty() ? $retailPrices->max() : null,
178:                 'min_wholesale' => $wholesalePrices->isNotEmpty() ? $wholesalePrices->min() : null,
179:                 'max_wholesale' => $wholesalePrices->isNotEmpty() ? $wholesalePrices->max() : null,
180:             ],
181:             'variants' => $product->variants->map(fn (ProductVariant $v) => $this->variant($v, $actor))->values()->all(),
182:             'readiness' => [
183:                 'ready' => ! collect($checks)->contains(fn ($c) => ! $c['ok']),
184:                 'checks' => $checks,
185:             ],
186:             'deep_link' => '#/products/'.$product->id,
187:         ];
188:     }
189: 
190:     /** @return array<string,mixed> */
191:     public function variant(ProductVariant $variant, User $actor): array
192:     {
193:         $out = [
194:             'id' => $variant->id,
195:             'product_id' => $variant->product_id,
196:             'sku' => $variant->sku,
197:             'barcode' => $variant->barcode,
198:             'color_name_ar' => $variant->color_name_ar,
199:             'color_name_en' => $variant->color_name_en,
200:             'color_hex' => $variant->color_hex,
201:             'size' => $variant->size,
202:             'capacity' => $variant->capacity,
203:             'retail_price' => $variant->retail_price !== null ? (float) $variant->retail_price : null,
204:             'wholesale_price' => $variant->wholesale_price !== null ? (float) $variant->wholesale_price : null,
205:             'compare_at_price' => $variant->compare_at_price !== null ? (float) $variant->compare_at_price : null,
206:             'reorder_level' => $variant->reorder_level !== null ? (int) $variant->reorder_level : null,
207:             'weight_kg' => $variant->weight_kg !== null ? (float) $variant->weight_kg : null,
208:             'is_active' => (bool) $variant->is_active,
209:             'deep_link' => '#/products/'.$variant->product_id,
210:         ];
211: 
212:         if (CostAccess::canView($actor)) {
213:             $out['cost_price'] = $variant->cost_price !== null ? (float) $variant->cost_price : null;
214:         }
215: 
216:         return $out;
217:     }
218: 
219:     /**
220:      * Build category path string like "حريمي › شنط إيد".
221:      */
222:     public function categoryPathString(?Category $category): string
223:     {
224:         if (! $category) {
225:             return 'جذر (قسم رئيسي)';
226:         }
227:         $parts = [];
228:         $seen = [];
229:         $curr = $category;
230:         while ($curr && ! isset($seen[$curr->id]) && count($seen) < 5) {
231:             $seen[$curr->id] = true;
232:             array_unshift($parts, $curr->name_ar);
233:             $curr = $curr->parent_id ? Category::find($curr->parent_id) : null;
234:         }
235: 
236:         return implode(' › ', $parts);
237:     }
238: 
239:     /**
240:      * Build UI category tree array for category_tree / category_tree_diff.
241:      *
242:      * @param  array<int, array<string,mixed>>  $overrides
243:      * @return list<array<string,mixed>>
244:      */
245:     public function categoryTreeSnapshot(array $overrides = []): array
246:     {
247:         $all = Category::query()
248:             ->withCount('products')
249:             ->orderBy('sort_order')
250:             ->orderBy('id')
251:             ->get();
252: 
253:         $rows = [];
254:         foreach ($all as $cat) {
255:             $row = [
256:                 'id' => (int) $cat->id,
257:                 'parent_id' => $cat->parent_id !== null ? (int) $cat->parent_id : null,
258:                 'name' => $cat->name_ar,
259:                 'slug' => $cat->slug,
260:                 'active' => (bool) $cat->is_active,
261:                 'sort_order' => (int) $cat->sort_order,
262:                 'products_count' => (int) ($cat->products_count ?? 0),
263:                 'deep_link' => '#/categories?focus='.$cat->id,
264:             ];
265:             if (isset($overrides[$cat->id])) {
266:                 $row = array_replace($row, $overrides[$cat->id]);
267:             }
268:             $rows[] = $row;
269:         }
270: 
271:         usort($rows, fn ($a, $b) => ($a['sort_order'] <=> $b['sort_order']) ?: ($a['id'] <=> $b['id']));
272: 
273:         $grouped = [];
274:         foreach ($rows as $r) {
275:             $key = $r['parent_id'] ?? 0;
276:             $grouped[$key][] = $r;
277:         }
278: 
279:         $build = function (int $parentKey) use (&$build, $grouped): array {
280:             $list = $grouped[$parentKey] ?? [];
281:             $out = [];
282:             foreach ($list as $item) {
283:                 $item['children'] = $build((int) $item['id']);
284:                 $out[] = $item;
285:             }
286: 
287:             return $out;
288:         };
289: 
290:         return $build(0);
291:     }
