153: 
154:         // M1: قيد الفرع يطبق أولًا — مقيّد بفرع ما يقدرش يوجّه branch_id لفرع تاني.
155:         // M6/L5: نفس الفلترة السلكية المحمية مع LIMIT.
156:         return Location::query()
157:             ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted), fn ($q) => $q->when($branchId !== null, fn ($w) => $w->where('branch_id', $branchId)))
158:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
