223:     public function customers(User $actor, string $query = '', array $filters = []): array
224:     {
225:         $q = Customer::query()
226:             ->when(($filters['business_only'] ?? false), fn ($x) => $x->whereIn('type', ['wholesale', 'distributor']))
227:             ->when(isset($filters['type']), fn ($x) => $x->where('type', $filters['type']))
228:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
229:             ->when(isset($filters['customer_group_id']), fn ($x) => $x->where('customer_group_id', $filters['customer_group_id']))
230:             ->when(isset($filters['pending_older_than_hours']), fn ($x) => $x->where('status', 'pending')->where('created_at', '<', now()->subHours((int) $filters['pending_older_than_hours'])));
231:         if (trim($query) !== '') {
232:             // L5: حرف أو اتنين مش بيستفيدوا من trigram.
233:             if (mb_strlen(trim($query)) < 3) {
234:                 return [];
235:             }
236:             if (preg_match('/^[0-9٠-٩۰-۹\s().+-]+$/u', trim($query))) {
237:                 // L5: LIKE مش ILIKE عشان يستخدم index الـ text_pattern_ops.
238:                 $q->whereLike('phone', SearchTerm::prefix(Customer::normalizePhone($query)), caseSensitive: true);
239:             } else {
240:                 $q->whereLike('search_text', SearchTerm::pattern($query), caseSensitive: false);
241:             }
242:         }
243: 
244:         return $q->orderBy('id')->limit(50)->get()
245:             ->map(fn (Customer $c) => [
246:                 'id' => $c->id,
247:                 'label' => $c->company_name ? $c->name.' — '.$c->company_name : $c->name,
248:                 'meta' => self::maskPhone($c->phone).' · '.self::statusLabel($c->status->value).' · '.self::typeLabel($c->type->value),
249:             ])
250:             ->values()
251:             ->all();
252:     }
