270:     /** @param list<string> $fields */
271:     public function matches(string $query, array $fields): bool
272:     {
273:         $nq = self::normalizeForSearch($query);
274:         if ($nq === '') {
275:             return true;
276:         }
277:         foreach ($fields as $f) {
278:             if (str_contains(self::normalizeForSearch($f), $nq)) {
279:                 return true;
280:             }
281:         }
282: 
283:         return false;
284:     }
