417:     /** @return list<array{id:int,label:string,meta:string}> */
418:     public function variants(User $actor, string $q = '', ?int $productId = null): array
419:     {
420:         $clean = trim(self::normalizeDigits($q));
421:         if ($clean !== '' && ! preg_match('/\s/u', $clean) && mb_strlen($clean) >= 4 && $productId === null) {
422:             $exact = $this->exactVariantByCode($clean);
423:             if ($exact) {
424:                 $exact->loadMissing('product:id,name_ar,code');
425: 
426:                 return [[
427:                     'id' => $exact->id,
428:                     'label' => ($exact->product?->name_ar ?? '').' — '.$exact->sku,
429:                     'meta' => trim(implode(' · ', array_filter([$exact->color_name_ar ?: $exact->color_name_en, $exact->size, $exact->capacity, $exact->is_active ? 'نشط' : 'معطّل']))),
430:                 ]];
431:             }
432:         }
433: 
434:         $terms = self::expandCatalogSearchTerms($clean);
435: 
436:         return ProductVariant::query()
437:             ->with('product:id,name_ar,name_en,code')
438:             ->when($productId !== null, fn ($x) => $x->where('product_id', $productId))
439:             ->when($terms !== [], function ($x) use ($terms, $clean): void {
440:                 $x->where(function ($w) use ($terms, $clean): void {
441:                     $w->whereRaw('LOWER(sku) = LOWER(?)', [$clean])
442:                         ->orWhereRaw('LOWER(barcode) = LOWER(?)', [$clean]);
443:                     foreach ($terms as $term) {
444:                         $pattern = SearchTerm::pattern($term);
445:                         $w->orWhereLike('sku', $pattern, caseSensitive: false)
446:                             ->orWhereLike('color_name_ar', $pattern, caseSensitive: false)
447:                             ->orWhereLike('color_name_en', $pattern, caseSensitive: false)
448:                             ->orWhereLike('size', $pattern, caseSensitive: false)
449:                             ->orWhereHas('product', fn ($p) => $p->whereLike('name_ar', $pattern, caseSensitive: false)->orWhereLike('name_en', $pattern, caseSensitive: false)->orWhereLike('code', $pattern, caseSensitive: false));
450:                     }
451:                 });
452:             })
453:             ->orderBy('id')
454:             ->limit(20)
455:             ->get()
456:             ->map(fn (ProductVariant $v) => [
457:                 'id' => $v->id,
458:                 'label' => ($v->product?->name_ar ?? '').' — '.$v->sku,
459:                 'meta' => trim(implode(' · ', array_filter([$v->color_name_ar ?: $v->color_name_en, $v->size, $v->capacity, $v->is_active ? 'نشط' : 'معطّل']))),
460:             ])
461:             ->values()
462:             ->all();
463:     }
