359:     private function finalizeAction(AiPendingAction $action, ToolOutcome $outcome): ToolOutcome
360:     {
361:         $ok = $outcome->type === 'result';
362:         $storedResult = $outcome->data;
363:         unset($storedResult['generated_password']);
364:         if ($ok && $this->registry->canUndo($action)) {
365:             $storedResult['undo_state'] = $this->registry->targetState($action);
366:         }
367:         $action->forceFill(['status' => $ok ? 'executed' : 'failed', 'result' => array_merge($storedResult, ['message' => $outcome->message]), 'executed_at' => $ok ? now() : null])->save();
