374:                 $blocks[0]['undo_action_id'] = $action->id;
375:             }
376:         } else {
377:             $blocks = [['type' => 'result', 'ok' => $ok, 'message' => $outcome->message ?? '']];
378:             if ($ok && $this->registry->canUndo($action)) {
379:                 $blocks[0]['undo_available_until'] = now()->addMinutes(15)->toIso8601String();
380:                 $blocks[0]['undo_action_id'] = $action->id;
