 664:     private function recentAudit(User $actor, array $args): ToolOutcome
 665:     {
 666:         $this->branches->assertCentralAccess($actor);
 667:         $days = max(1, min(90, (int) ($args['days'] ?? 7)));
 668:         $rows = DB::table('staff_audit_logs')->where('created_at', '>=', now()->subDays($days))->orderByDesc('id')->limit(50)->get(['id', 'actor_id', 'action', 'target_type', 'target_id', 'created_at'])->map(fn ($r) => (array) $r)->all();
 669: 
 670:         return ToolOutcome::data(['audit' => $rows]);
 671:     }
