 673:     private function picker(User $actor, array $args): ToolOutcome
 674:     {
 675:         $type = (string) ($args['entity_type'] ?? 'branch');
 676:         $query = (string) ($args['query'] ?? '');
 677:         if (! $this->canReadEntity($actor, $type)) {
 678:             return ToolOutcome::denied('معندكش صلاحية عرض النوع ده.');
 679:         }
 680:         $options = match ($type) {
 681:             'branch' => $this->resolver->branches($actor, $query),
 682:             'user' => $this->resolver->users($actor, $query),
 683:             'role' => $this->resolver->roles($query),
 684:             'location' => $this->resolver->locations($actor, $query),
 685:             'customer' => $this->resolver->customers($actor, $query),
 686:             'customer_group' => $this->resolver->customerGroups($query),
 687:             'category' => $this->resolver->categories($actor, $query),
 688:             'product' => $this->resolver->products($actor, $query),
 689:             'variant' => $this->resolver->variants($actor, $query),
 690:             default => [],
 691:         };
 692: 
 693:         return ToolOutcome::picker(['type' => 'entity_picker', 'entity' => $type, 'purpose' => (string) ($args['purpose'] ?? ''), 'multi' => false, 'options' => $options]);
