 774:     /**
 775:      * 5.4: كارت الترحيب للكتالوج — query واحدة مجمعة + cache لمدة 60 ثانية لكل مستخدم.
 776:      *
 777:      * @return array<string,mixed>
 778:      */
 779:     public function catalogWelcomeBlock(User $actor): array
 780:     {
 781:         $stats = Cache::remember('ai:catalog-welcome:'.$actor->id, 60, function (): array {
 782:             $row = DB::selectOne("
 783:                 SELECT
 784:                     COUNT(*) FILTER (WHERE p.status = 'draft') AS drafts_count,
 785:                     COUNT(*) FILTER (
 786:                         WHERE NOT EXISTS (
 787:                             SELECT 1 FROM media m
 788:                             WHERE m.collection_name = 'images'
 789:                               AND (
 790:                                 (m.model_type = 'App\\\\Models\\\\Product' AND m.model_id = p.id)
 791:                                 OR (
 792:                                     m.model_type = 'App\\\\Models\\\\ProductVariant'
 793:                                     AND m.model_id IN (
 794:                                         SELECT pv.id FROM product_variants pv
 795:                                         WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 796:                                     )
 797:                                 )
 798:                               )
 799:                         )
 800:                     ) AS missing_images_count,
 801:                     COUNT(*) FILTER (
 802:                         WHERE EXISTS (
 803:                             SELECT 1 FROM product_variants pv
 804:                             WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 805:                               AND (
 806:                                 (p.sales_channel IN ('retail', 'both') AND (pv.retail_price IS NULL OR pv.retail_price <= 0))
 807:                                 OR (p.sales_channel IN ('wholesale', 'both') AND (pv.wholesale_price IS NULL OR pv.wholesale_price <= 0))
 808:                               )
 809:                         )
 810:                     ) AS missing_prices_count,
 811:                     COUNT(*) FILTER (
 812:                         WHERE p.status = 'draft'
 813:                           AND EXISTS (
 814:                               SELECT 1 FROM categories c
 815:                               LEFT JOIN categories p1 ON p1.id = c.parent_id AND p1.deleted_at IS NULL
 816:                               LEFT JOIN categories p2 ON p2.id = p1.parent_id AND p2.deleted_at IS NULL
 817:                               WHERE c.id = p.category_id AND c.deleted_at IS NULL
 818:                                 AND c.is_active = TRUE
 819:                                 AND (c.parent_id IS NULL OR (p1.id IS NOT NULL AND p1.is_active = TRUE AND (p1.parent_id IS NULL OR (p2.id IS NOT NULL AND p2.is_active = TRUE AND p2.parent_id IS NULL))))
 820:                           )
 821:                           AND EXISTS (
