1416:     private function prepCreateRole(User $actor, AiConversation $conv, array $args): ToolOutcome
1417:     {
1418:         try {
1419:             $this->branches->assertCentralAccess($actor);
1420:         } catch (\Throwable) {
1421:             return ToolOutcome::denied('إنشاء الأدوار محتاج وصول مركزي.');
1422:         }
1423:         $name = StaffRole::normalizeName((string) ($args['name'] ?? ''));
1424:         if ($name === '' || StaffRole::isReserved($name)) {
1425:             return ToolOutcome::denied('اسم الدور محجوز أو فاضي.');
1426:         }
1427:         $perms = array_values(array_unique($args['permissions'] ?? []));
1428:         if (! StaffAdministration::mayGrantPermissions($actor, $perms)) {
1429:             return ToolOutcome::denied('لا يمكنك إسناد صلاحيات لا تملكها.');
1430:         }
1431:         $sensitive = array_filter($perms, fn ($p) => str_ends_with($p, '.manage') || in_array($p, ['ai_agent.execute', 'ai_agent.settings', 'settings.manage'], true));
1432: 
