1744:     private function prepReactivateCustomer(User $actor, AiConversation $conv, array $args): ToolOutcome
1745:     {
1746:         $customer = $this->findCustomer($args);
1747:         if (! $customer) {
1748:             return ToolOutcome::denied('العميل مش موجود.');
1749:         }
1750:         if ($customer->status !== CustomerStatus::Suspended) {
1751:             return ToolOutcome::denied('الحساب مش موقوف.');
1752:         }
1753: 
1754:         $target = CustomerStatus::tryFrom((string) $customer->pre_suspension_status)?->value
1755:             ?? ($customer->approved_at ? CustomerStatus::Approved->value : CustomerStatus::Pending->value);
1756: 
1757:         return $this->makeProposal($actor, $conv, 'reactivate_customer', ['customer_id' => $customer->id], ['customer:'.$customer->id => $this->customerVersion($customer)], ['title' => 'إعادة تفعيل '.$customer->name, 'before' => ['status' => CustomerStatus::Suspended->value], 'after' => ['status' => $target], 'warnings' => []], ['suspension_reason' => $customer->suspension_reason], 'medium');
1758:     }
