2107:     private function execUpdateRolePerms(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2108:     {
2109:         $role = Role::findOrFail($args['role_id']);
2110:         $current = $role->permissions()->pluck('name')->all();
2111:         $next = array_values(array_unique(array_merge(array_diff($current, $args['remove'] ?? []), $args['add'] ?? [])));
2112:         $failure = app(UpdateRole::class)($actor, $role, ['permissions' => $next, 'expected_version' => (int) ($action->expected_versions['role:'.$role->id] ?? $role->lock_version)], $via);
2113:         if ($failure) {
2114:             return ToolOutcome::result(false, 'الدور محمي من التعديل.');
