 75:             throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
 76:         }
 77: 
 78:         // F2: logo changes run outside the row lock (see create()).
 79:         $removeLogo = (bool) ($data['remove_logo'] ?? false);
 80:         if ($logo) {
 81:             $this->attachLogo($updated, $logo);
 82:         } elseif ($removeLogo) {
 83:             DB::transaction(fn () => $updated->clearMediaCollection('logo'));
