101:     public function update(Product $product, array $data, User $user): Product
102:     {
103:         $expectedVersion = $data['expected_version'] ?? null;
104:         unset($data['expected_version']);
105:         if (! empty($data['expected_updated_at']) && $expectedVersion === null) {
106:             throw new BusinessException('أعد تحميل المنتج لإرسال رقم الإصدار قبل الحفظ.', ['expected_version' => ['رقم الإصدار مطلوب.']]);
107:         }
108:         unset($data['expected_updated_at']);
109: 
110:         // F8: a concurrent update can win the slug between validation and the
111:         // write — surface it as 409, not 500.
112:         try {
113:             return DB::transaction(function () use ($product, $data, $user, $expectedVersion) {
114:                 CatalogLock::tree(shared: true);
115:                 // قفل صف المنتج طول التعديل عشان فحص النشر ميعديش مع تعديل متزامن
116:                 $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
117: 
118:                 if ($expectedVersion !== null && (int) $expectedVersion !== (int) $product->lock_version) {
119:                     throw new BusinessException('المنتج تعدّل في جلسة أخرى؛ أعد تحميل الصفحة وحاول مجددًا.', [], 409);
120:                 }
121: 
122:                 unset($data['brand_id'], $data['supplier_id']);
123:                 $newStatus = isset($data['status']) ? ProductStatus::from($data['status']) : null;
124:                 unset($data['status']);
125: 
126:                 if (array_key_exists('slug', $data) && empty($data['slug'])) {
127:                     $data['slug'] = SlugService::make(Product::class, $data['name_en'] ?? $product->name_en, $product->id);
128:                 }
129:                 $this->lockReference(Category::class, (int) ($data['category_id'] ?? $product->category_id), 'category_id');
130: 
131:                 if (array_key_exists('is_featured', $data) && $data['is_featured'] === null) {
132:                     unset($data['is_featured']);
133:                 }
134: 
135:                 $product->update($data);
136: 
137:                 if ($newStatus && $newStatus !== $product->status) {
138:                     $this->changeStatus($product, $newStatus, $user);
139:                 } elseif ($product->status === ProductStatus::Published) {
140:                     // تعديل من غير تغيير حالة على منتج منشور: القواعد بتتفحص من جديد
141:                     $this->assertPublishable($product);
142:                 }
143: 
144:                 return $product->fresh(['category.media', 'variants.media', 'media']);
145:             });
146:         } catch (UniqueConstraintViolationException $e) {
147:             // L3: same rule as create() — only blame the slug on a slug
148:             // constraint; anything else is a real conflict, not a 409 guess.
149:             $driverMessage = (string) ($e->errorInfo[2] ?? $e->getMessage());
150:             if (str_contains($driverMessage, 'products_slug_lower_unique') || str_contains($driverMessage, '(slug)')) {
151:                 throw new BusinessException('المعرف (slug) مستخدم بالفعل؛ اختر قيمة أخرى.', [], 409);
152:             }
153: 
154:             throw $e;
155:         }
156:     }
