158:     private function replayCreation(Product $product, string $requestHash): Product
159:     {
160:         if ($product->trashed()) {
161:             throw new BusinessException('المنتج الخاص بطلب الإنشاء محذوف بالفعل.', [], 409);
162:         }
163:         if ($product->create_request_hash !== null && ! hash_equals($product->create_request_hash, $requestHash)) {
164:             throw new BusinessException('تم إنشاء المنتج من الطلب السابق ببيانات مختلفة؛ أعد تحميله قبل التعديل.', ['product_id' => [$product->id]], 409);
165:         }
166: 
167:         return $product->fresh(['category.media', 'variants.media', 'media']);
168:     }
169: 
170:     public function changeStatus(Product $product, ProductStatus $status, User $user): void
171:     {
172:         DB::transaction(function () use ($product, $status, $user): void {
173:             CatalogLock::tree(shared: true);
174:             // قفل صف المنتج وقسمه قبل الفحص والنشر، عشان مفيش تعديل متزامن يعدي بين الفحص والحفظ
175:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
176:             if ($product->category_id) {
177:                 $this->lockReference(Category::class, (int) $product->category_id, 'category_id');
178:             }
179:             $product->refresh();
180: 
181:             if ($product->status !== $status && ($product->status === ProductStatus::Published || $status === ProductStatus::Published) && ! $user->can('products.publish')) {
182:                 throw new BusinessException('ليس لديك صلاحية تغيير نشر المنتجات', [], 403);
183:             }
184: 
185:             if ($status === ProductStatus::Published) {
186:                 $this->assertPublishable($product);
187:                 $product->published_at ??= now();
188:             }
189:             $product->status = $status;
190:             $product->save();
191:         });
192:         $product->refresh();
193:     }
194: 
195:     public function assertPublishable(Product $product): void
196:     {
197:         $this->publishability->assertPublishable($product);
198:     }
