200:     private function lockReference(string $model, int $id, string $field): void
201:     {
202:         if (! $model::whereKey($id)->sharedLock()->first()) {
203:             throw new BusinessException('أحد المراجع المطلوبة لم يعد متاحًا', [$field => ['القيمة المحددة غير موجودة أو محذوفة']]);
204:         }
205:     }
