135:     /**
136:      * Return all settings grouped by their group name, with values cast to their declared types.
137:      * Numbering counters are read fresh because they change for every generated document number.
138:      *
139:      * @return array<string, array<string, mixed>>
140:      */
141:     public function getAllGrouped(): array
142:     {
143:         $grouped = $this->staticSettings();
144: 
145:         $counters = Setting::query()
146:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
147:             ->orderBy('key')
148:             ->get()
149:             ->mapWithKeys(fn (Setting $setting): array => [
150:                 $setting->key => $this->castValue($setting->value, $setting->type),
151:             ])
152:             ->all();
153: 
154:         if (isset($counters['movement_next_number'])) {
155:             $counters['movement_next_number'] = $this->nextMovementNumber();
156:         }
157:         foreach (self::SEQUENCE_TYPES as $type => $key) {
158:             if (isset($counters[$key])) {
159:                 $counters[$key] = $this->nextDocumentNumber($type);
160:             }
161:         }
162: 
163:         if ($counters !== []) {
164:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
165:             ksort($grouped['numbering']);
166:         }
167: 
168:         return $grouped;
169:     }
