171:     private function staticSettings(): array
172:     {
173:         $read = function (): array {
174:             return Setting::query()
175:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
176:                 ->orderBy('group')
177:                 ->orderBy('key')
178:                 ->get()
179:                 ->groupBy('group')
180:                 ->map(fn ($settings): array => $settings
181:                     ->mapWithKeys(fn (Setting $setting): array => [
182:                         $setting->key => $this->castValue($setting->value, $setting->type),
183:                     ])
184:                     ->all())
185:                 ->all();
186:         };
187: 
188:         $inTransaction = DB::transactionLevel() > 0;
189:         if ($inTransaction && $this->transactionSnapshot !== null) {
190:             return $this->transactionSnapshot;
191:         }
192:         if ($inTransaction && $this->uncommittedSettings) {
193:             return $this->transactionSnapshot = $read();
194:         }
195:         $version = Cache::get(self::CACHE_VERSION_KEY);
196:         if (! is_string($version)) {
197:             Cache::add(self::CACHE_VERSION_KEY, (string) Str::uuid());
198:             $version = Cache::get(self::CACHE_VERSION_KEY);
199:         }
200: 
201:         // M-6: خارج الـ transactions تُحفظ النتيجة في ذاكرة الطلب — كل get()
202:         // كان يكلف رحلتين للكاش وفك تسلسل المصفوفة كاملة.
203:         if ($this->requestCache !== null) {
204:             return $this->requestCache;
205:         }
206:         $key = self::CACHE_KEY.':'.$version;
207:         if ($inTransaction) {
208:             // Reuse committed cache values, but never publish an uncommitted cache miss.
209:             return $this->transactionSnapshot = Cache::get($key) ?? $read();
210:         }
211: 
212:         $result = Cache::remember($key, self::CACHE_TTL_SECONDS, $read);
213:         // كاتب متأخر قد يدير النسخة أثناء القراءة — لقطة قديمة لا تُحفظ
214:         // في ذاكرة الطلب، وإلا التصقت القيمة القديمة بباقي الطلب.
215:         if (Cache::get(self::CACHE_VERSION_KEY) === $version) {
216:             $this->requestCache = $result;
217:         }
218: 
219:         return $result;
220:     }
