 24:             throw new \RuntimeException('Catalog demo data cannot be seeded in production.');
 25:         }
 26:         DB::transaction(function (): void {
 27:             $categories = $this->seedCategories();
 28:             $brands = $this->seedBrands();
 29:             $this->seedProducts($categories, $brands);
 30:         });
 31:     }
 32: 
 33:     /** @return array<string, Category> */
 34:     private function seedCategories(): array
 35:     {
 36:         $tree = [
 37:             ['name_ar' => 'شنط يد', 'name_en' => 'Handbags', 'slug' => 'handbags'],
 38:             ['name_ar' => 'محافظ', 'name_en' => 'Wallets', 'slug' => 'wallets'],
 39:             ['name_ar' => 'شنط سفر', 'name_en' => 'Luggage', 'slug' => 'luggage', 'children' => [
 40:                 ['name_ar' => 'كابينة', 'name_en' => 'Cabin', 'slug' => 'cabin'],
 41:                 ['name_ar' => 'متوسطة', 'name_en' => 'Medium', 'slug' => 'medium'],
 42:                 ['name_ar' => 'كبيرة', 'name_en' => 'Large', 'slug' => 'large'],
 43:             ]],
 44:             ['name_ar' => 'شنط ظهر', 'name_en' => 'Backpacks', 'slug' => 'backpacks'],
 45:         ];
 46: 
 47:         $categories = [];
 48:         foreach ($tree as $i => $node) {
 49:             $parent = Category::firstOrCreate(
 50:                 ['slug' => $node['slug']],
 51:                 ['name_ar' => $node['name_ar'], 'name_en' => $node['name_en'], 'sort_order' => $i, 'is_active' => true],
 52:             );
 53:             $categories[$node['slug']] = $parent;
 54:             foreach ($node['children'] ?? [] as $j => $child) {
 55:                 $categories[$child['slug']] = Category::firstOrCreate(
 56:                     ['slug' => $child['slug']],
 57:                     ['parent_id' => $parent->id, 'name_ar' => $child['name_ar'], 'name_en' => $child['name_en'], 'sort_order' => $j, 'is_active' => true],
 58:                 );
 59:             }
 60:         }
 61: 
 62:         return $categories;
 63:     }
 64: 
 65:     /** @return array<string, Brand> */
 66:     private function seedBrands(): array
 67:     {
 68:         $brands = [];
 69:         foreach ([
 70:             ['name_ar' => 'ميلانو', 'name_en' => 'Milano', 'slug' => 'milano'],
 71:             ['name_ar' => 'فوياجر', 'name_en' => 'Voyager', 'slug' => 'voyager'],
 72:             ['name_ar' => 'أطلس', 'name_en' => 'Atlas', 'slug' => 'atlas'],
 73:             ['name_ar' => 'لونا', 'name_en' => 'Luna', 'slug' => 'luna'],
 74:         ] as $i => $brand) {
 75:             $brands[$brand['slug']] = Brand::firstOrCreate(
 76:                 ['slug' => $brand['slug']],
 77:                 ['name_ar' => $brand['name_ar'], 'name_en' => $brand['name_en'], 'is_active' => true],
 78:             );
 79:         }
 80: 
 81:         return $brands;
 82:     }
 83: 
 84:     /**
 85:      * @param  array<string, Category>  $categories
 86:      * @param  array<string, Brand>  $brands
 87:      */
 88:     private function seedProducts(array $categories, array $brands): void
 89:     {
 90:         if (Product::query()->exists()) {
 91:             return; // البيانات التجريبية بتتزرع مرة واحدة بس
 92:         }
 93: 
 94:         $author = User::query()->first();
 95:         if (! $author) {
 96:             throw new \RuntimeException('Create a staff user before seeding the demo catalog.');
 97:         }
 98: 
 99:         $service = app(ProductService::class);
100:         foreach ($this->catalog($categories, $brands) as $data) {
101:             $service->create($data, $author);
102:         }
103:     }
104: 
