 8: export interface ToolStatRow { tool: string; total: number; executed: number; cancelled: number; failed_409: number; confirm_rate: number; cancel_rate: number; needs_attention: boolean }
 9: export interface ToolStatsSummary { total_proposals: number; executed_count: number; cancelled_count: number; failed_409_count: number; confirm_rate: number; cancel_rate: number; conflict_409_rate: number; tools: ToolStatRow[] }
10: export interface UploadedAttachment { id: string; filename: string; mime: string; size: number; thumb_url: string }
11: export const assistantApi = {
12:   list: () => api.get<{ data: Conv[] }>(`${BASE}/conversations`).then(r => r.data.data ?? (r.data as unknown as Conv[])),
13:   listPaginated: (page = 1, q = '', all = false) => api.get<{ data: Conv[]; last_page: number }>(`${BASE}/conversations`, { params: { page, per_page: 20, q, ...(all ? { all: 1 } : {}) } }).then(r => r.data),
14:   pin: (id: number, is_pinned: boolean) => api.patch(`${BASE}/conversations/${id}/pin`, { is_pinned }),
15:   settings: () => api.get<{ data: AgentSettings; tools: string[] }>(`${BASE}/settings`).then(r => r.data),
16:   saveSettings: (data: AgentSettings, expected: AgentSettings) => api.put(`${BASE}/settings`, { ...data, expected }),
17:   usage: (all: boolean) => api.get<{ data: { day: string; input_tokens: number; output_tokens: number }[]; tool_stats?: ToolStatsSummary }>(`${BASE}/usage`, { params: { ...(all ? { all: 1 } : {}) } }).then(r => r.data.data),
18:   usageWithStats: (all: boolean) => api.get<{ data: { day: string; input_tokens: number; output_tokens: number }[]; tool_stats?: ToolStatsSummary }>(`${BASE}/usage`, { params: { ...(all ? { all: 1 } : {}) } }).then(r => r.data),
19:   create: () => api.post<{ data: Conv }>(`${BASE}/conversations`).then(r => r.data.data),
20:   show: (id: number) => api.get<{ data: Conv }>(`${BASE}/conversations/${id}`).then(r => r.data.data),
21:   remove: (id: number) => api.delete(`${BASE}/conversations/${id}`),
22:   uploadAttachments: (id: number, files: File[]) => {
23:     const form = new FormData();
24:     files.forEach(file => form.append('files[]', file));
25:     return api.post<{ data: UploadedAttachment[] }>(`${BASE}/conversations/${id}/attachments`, form, { headers: { 'Content-Type': 'multipart/form-data' } }).then(r => r.data.data);
26:   },
27:   send: (id: number, body: { text: string; selection?: { entity: string; id: number | string; label?: string }; mentions?: { entity: string; id: number | string }[]; attachments?: string[] }) =>
28:     api.post<{ data: { text: string; ui_blocks: UiBlock[]; message_id: number } }>(`${BASE}/conversations/${id}/messages`, body, { timeout: 600000 }).then(r => r.data.data),
29:   stream: async (id: number, body: { text: string; selection?: { entity: string; id: number | string; label?: string }; mentions?: { entity: string; id: number | string }[]; attachments?: string[] }, onStatus: (message: string) => void) => {
30:     // L6: تحليل الإطارات الجديدة فقط — إعادة تحليل كامل responseText في
31:     // كل chunk كانت O(n²) وتجمّد الواجهة مع الردود الطويلة.
32:     const parser = createIncrementalSseParser();
33:     const response = await api.post<string>(`${BASE}/conversations/${id}/stream`, body, {
34:       timeout: 600000, responseType: 'text', headers: { Accept: 'text/event-stream' },
35:       onDownloadProgress: progress => {
36:         const text = (progress.event?.target as XMLHttpRequest | undefined)?.responseText;
37:         if (typeof text !== 'string') return;
38:         const statuses = parser.feed(text).filter(e => e.event === 'status');
39:         const latest = statuses.at(-1)?.data.message;
40:         if (typeof latest === 'string') onStatus(latest);
41:       },
42:     });
43:     const events = parseAgentEvents(response.data);
44:     const failure = events.find(e => e.event === 'error');
45:     if (failure) throw { response: { data: { message: String(failure.data.message) } } };
46:     if (!events.some(e => e.event === 'reply')) throw new Error('المحادثة انقطعت قبل اكتمال الرد.');
47:   },
48:   confirm: (actionId: string, typed_confirmation?: string, selected_items?: string[]) =>
49:     api.post<{ data: { ok: boolean; message: string; result: Record<string, unknown>; ui_block: UiBlock; status: string } }>(`${BASE}/actions/${actionId}/confirm`, { typed_confirmation, selected_items }).then(r => r.data.data),
50:   cancel: (actionId: string) => api.post<{ data: { status: string } }>(`${BASE}/actions/${actionId}/cancel`).then(r => r.data.data),
51:   undo: (actionId: string) => api.post<{ data: { ok: boolean; message: string; status: string } }>(`${BASE}/actions/${actionId}/undo`).then(r => r.data.data),
52:   welcome: () => api.get<{ data: UiBlock | null }>(`${BASE}/welcome`).then(r => r.data.data),
53:   mentions: (q: string) => api.get<{ data: Record<string, { id: number | string; label: string; meta?: string }[]> }>(`${BASE}/mentions`, { params: { q } }).then(r => r.data.data),
