221: /* ---------- Shell ---------- */
222: .as-shell { display: grid; grid-template-columns: var(--as-sidebar) minmax(0, 1fr); height: 100%; }
223: .as-shell[data-collapsed='true'] { grid-template-columns: 0 minmax(0, 1fr); }
224: .as-shell[data-collapsed='true'] .as-sidebar { visibility: hidden; }
225: 
226: /* ---------- Sidebar ---------- */
227: .as-sidebar { display: flex; flex-direction: column; min-height: 0; min-width: 0; background: var(--as-surface); border-inline-end: 1px solid var(--as-border); overflow: hidden; }
228: .as-brand { display: flex; align-items: center; gap: .65rem; padding: 1rem 1rem .75rem; }
229: .as-mark { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; color: #fff; background: linear-gradient(140deg, var(--as-accent), var(--as-primary)); box-shadow: 0 4px 12px -4px var(--as-primary-ring); flex: none; }
230: .as-brand h1 { font-size: 1rem; font-weight: 700; line-height: 1.3; }
231: .as-brand > div { min-width: 0; }
232: .as-brand p { font-size: .75rem; color: var(--as-muted); line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
233: .as-brand .as-iconbtn { margin-inline-start: auto; }
234: .as-sidebar-tools { display: grid; gap: .5rem; padding: 0 1rem .75rem; }
235: .as-convlist { flex: 1; overflow-y: auto; padding: 0 .5rem 1rem; scrollbar-width: thin; }
236: .as-group-label { position: sticky; top: 0; z-index: 1; display: flex; align-items: center; gap: .35rem; padding: .7rem .6rem .3rem; font-size: .72rem; font-weight: 600; color: var(--as-faint); background: var(--as-surface); letter-spacing: .01em; }
237: .as-conv { position: relative; display: flex; align-items: center; border-radius: var(--as-radius-sm); transition: background .12s; }
238: .as-conv:hover { background: var(--as-surface-2); }
239: .as-conv[data-active='true'] { background: var(--as-primary-soft); }
240: .as-conv[data-active='true']::before { content: ''; position: absolute; inset-inline-start: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 3px; background: var(--as-primary); }
241: .as-conv-open { flex: 1; min-width: 0; display: grid; gap: 1px; padding: .55rem .7rem; text-align: start; border-radius: var(--as-radius-sm); }
242: .as-conv-title { font-size: .88rem; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
243: .as-conv[data-active='true'] .as-conv-title { color: var(--as-primary); font-weight: 600; }
244: .as-conv-meta { display: flex; align-items: center; gap: .4rem; font-size: .72rem; color: var(--as-faint); }
245: .as-conv-meta .as-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--as-warning); }
246: .as-conv-actions { display: flex; gap: 2px; padding-inline-end: .3rem; opacity: 0; transition: opacity .12s; }
247: .as-conv:hover .as-conv-actions, .as-conv:focus-within .as-conv-actions, .as-conv[data-confirming='true'] .as-conv-actions { opacity: 1; }
248: .as-conv-actions [aria-pressed='true'] { color: var(--as-primary); }
249: .as-conv-delete-confirm { display: flex; gap: 4px; align-items: center; padding-inline-end: .35rem; }
250: .as-sidebar-foot { white-space: nowrap; padding: .75rem 1rem; border-top: 1px solid var(--as-border); display: flex; align-items: center; gap: .5rem; font-size: .75rem; color: var(--as-muted); }
251: .as-meter { flex: 1; height: 5px; border-radius: 99px; background: var(--as-surface-3); overflow: hidden; }
252: .as-meter > span { display: block; height: 100%; border-radius: inherit; background: var(--as-success); }
253: .as-meter[data-level='warn'] > span { background: var(--as-warning); }
254: .as-meter[data-level='high'] > span { background: var(--as-danger); }
255: 
256: /* list empty states */
257: .as-list-empty { display: grid; justify-items: center; gap: .5rem; text-align: center; padding: 2.5rem 1rem; color: var(--as-muted); font-size: .85rem; }
258: .as-list-empty .as-empty-icon { width: 44px; height: 44px; border-radius: 12px; display: grid; place-items: center; background: var(--as-surface-2); color: var(--as-faint); }
259: .as-list-empty strong { color: var(--as-text); font-weight: 600; font-size: .9rem; }
260: .as-skel { height: 44px; border-radius: var(--as-radius-sm); margin: .35rem .2rem; background: linear-gradient(90deg, var(--as-surface-2) 30%, var(--as-surface-3) 50%, var(--as-surface-2) 70%); background-size: 300% 100%; animation: as-shimmer 1.4s infinite linear; }
261: @keyframes as-shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }
262: 
263: /* ---------- Main ---------- */
264: .as-main { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; }
265: .as-topbar { display: flex; align-items: center; gap: .5rem; min-height: 60px; padding: .6rem 1rem; border-bottom: 1px solid var(--as-border); background: color-mix(in oklab, var(--as-bg) 82%, transparent); backdrop-filter: blur(10px); z-index: 2; }
266: .as-topbar-title { flex: 1; min-width: 0; display: grid; }
267: .as-topbar-title h2 { font-size: .98rem; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; line-height: 1.4; }
268: .as-topbar-title span { font-size: .74rem; color: var(--as-muted); line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
269: .as-tabs { display: inline-flex; padding: 3px; gap: 2px; border-radius: 11px; background: var(--as-surface-2); border: 1px solid var(--as-border); }
270: .as-tab { display: inline-flex; align-items: center; gap: .4rem; min-height: 32px; padding: 0 .75rem; border-radius: 8px; font-size: .84rem; font-weight: 500; color: var(--as-muted); transition: background .15s, color .15s; }
271: .as-tab[aria-selected='true'] { background: var(--as-surface); color: var(--as-text); box-shadow: var(--as-shadow-sm), 0 0 0 1px var(--as-border); }
272: .as-status-chip { display: inline-flex; align-items: center; gap: .4rem; padding: .2rem .6rem; border-radius: 99px; font-size: .75rem; background: var(--as-success-soft); color: var(--as-success); white-space: nowrap; }
273: .as-status-chip::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
274: .as-status-chip[data-busy='true'] { background: var(--as-primary-soft); color: var(--as-primary); }
275: .as-status-chip[data-busy='true']::before { animation: as-pulse 1s infinite; }
276: @keyframes as-pulse { 50% { opacity: .25; } }
277: 
278: /* ---------- Feed ---------- */
279: .as-feed { flex: 1; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; }
280: .as-feed-inner { width: 100%; max-width: 820px; margin-inline: auto; padding: 1.5rem 1.25rem 1rem; display: grid; gap: 1.4rem; }
281: .as-msg { display: grid; gap: .6rem; animation: as-in .28s ease both; }
282: @keyframes as-in { from { opacity: 0; translate: 0 6px; } }
283: .as-msg--user { justify-items: end; }
284: .as-msg-head { display: flex; align-items: center; gap: .5rem; font-size: .78rem; color: var(--as-muted); }
285: .as-avatar { width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; background: linear-gradient(140deg, var(--as-accent), var(--as-primary)); color: #fff; flex: none; }
286: .as-msg-head strong { color: var(--as-text); font-weight: 600; }
287: .as-msg-body { padding-inline-start: 34px; display: grid; gap: .75rem; min-width: 0; }
288: .as-bubble { max-width: min(85%, 620px); padding: .65rem 1rem; border-radius: 16px; border-start-end-radius: 5px; background: var(--as-user-bubble); color: var(--as-user-text); white-space: pre-wrap; overflow-wrap: anywhere; box-shadow: var(--as-shadow-sm); }
289: .as-msg-user-meta { font-size: .72rem; color: var(--as-faint); white-space: nowrap; }
290: .as-mention-inline { display: inline-flex; gap: .25rem; flex-wrap: wrap; }
291: .as-msg-tools { display: flex; gap: 2px; opacity: 0; transition: opacity .15s; }
292: .as-msg:hover .as-msg-tools, .as-msg:focus-within .as-msg-tools { opacity: 1; }
293: 
294: /* Rich text (assistant) */
295: .as-rich { display: grid; gap: .55rem; overflow-wrap: anywhere; }
296: .as-rich p { white-space: pre-wrap; }
297: .as-rich h4 { font-size: 1rem; font-weight: 700; margin-top: .35rem; }
298: .as-rich ul, .as-rich ol { padding-inline-start: 1.35rem; display: grid; gap: .2rem; }
299: .as-rich li::marker { color: var(--as-faint); }
300: .as-rich strong { font-weight: 700; }
301: .as-rich :not(pre) > code { font-size: .84em; padding: .1em .4em; border-radius: 5px; background: var(--as-surface-2); border: 1px solid var(--as-border); }
302: .as-rich blockquote { margin: 0; padding: .35rem .85rem; border-inline-start: 3px solid var(--as-border-strong); color: var(--as-muted); }
303: .as-code { border-radius: var(--as-radius-sm); border: 1px solid var(--as-border); background: var(--as-surface-2); overflow: hidden; }
304: .as-code-head { display: flex; align-items: center; justify-content: space-between; padding: .25rem .4rem .25rem .75rem; font-size: .72rem; color: var(--as-muted); border-bottom: 1px solid var(--as-border); direction: ltr; }
305: .as-code pre { margin: 0; padding: .8rem 1rem; overflow-x: auto; text-align: left; font-size: .82rem; line-height: 1.6; white-space: pre; }
306: 
307: /* Thinking / streaming */
308: .as-thinking { display: grid; gap: .5rem; padding: .85rem 1rem; border-radius: var(--as-radius); background: var(--as-surface); border: 1px solid var(--as-border); box-shadow: var(--as-shadow-sm); max-width: 520px; }
309: .as-thinking-now { display: flex; align-items: center; gap: .6rem; font-weight: 500; font-size: .9rem; }
310: .as-thinking-now span { background: linear-gradient(90deg, var(--as-text) 0%, var(--as-faint) 50%, var(--as-text) 100%); background-size: 200% 100%; -webkit-background-clip: text; background-clip: text; color: transparent; animation: as-shine 2s linear infinite; }
311: @keyframes as-shine { to { background-position: -200% 0; } }
312: .as-dots { display: inline-flex; gap: 3px; }
313: .as-dots i { width: 6px; height: 6px; border-radius: 50%; background: var(--as-primary); animation: as-bounce 1.1s infinite ease-in-out; }
314: .as-dots i:nth-child(2) { animation-delay: .15s; } .as-dots i:nth-child(3) { animation-delay: .3s; }
315: @keyframes as-bounce { 0%, 80%, 100% { opacity: .25; scale: .7; } 40% { opacity: 1; scale: 1; } }
316: .as-steps { list-style: none; display: grid; gap: .25rem; font-size: .8rem; color: var(--as-muted); }
317: .as-steps li { display: flex; align-items: center; gap: .45rem; }
318: .as-steps .as-icon { color: var(--as-success); }
319: .as-thinking-time { font-size: .72rem; color: var(--as-faint); }
320: 
321: /* Empty / welcome */
322: .as-welcome { min-height: 100%; display: grid; align-content: center; justify-items: center; gap: 1.5rem; padding: 2rem 1.25rem; text-align: center; max-width: 760px; margin-inline: auto; }
323: .as-welcome-mark { width: 60px; height: 60px; border-radius: 18px; display: grid; place-items: center; color: #fff; background: linear-gradient(140deg, var(--as-accent), var(--as-primary)); box-shadow: 0 14px 34px -12px var(--as-primary-ring); }
324: .as-welcome h3 { font-size: 1.5rem; font-weight: 700; line-height: 1.45; }
325: .as-welcome p { color: var(--as-muted); max-width: 44ch; text-wrap: pretty; }
326: .as-starters { width: 100%; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .6rem; }
327: .as-starter { display: grid; gap: .3rem; padding: .85rem 1rem; text-align: start; border-radius: var(--as-radius); border: 1px solid var(--as-border); background: var(--as-surface); transition: border-color .15s, box-shadow .15s, transform .15s; }
328: .as-starter:hover:not(:disabled) { border-color: var(--as-primary-ring); box-shadow: var(--as-shadow); transform: translateY(-1px); }
329: .as-starter-top { display: flex; align-items: center; gap: .45rem; font-size: .76rem; color: var(--as-primary); font-weight: 600; }
330: .as-starter-text { font-size: .9rem; color: var(--as-text); line-height: 1.55; }
331: .as-hints { display: flex; flex-wrap: wrap; justify-content: center; gap: .4rem .9rem; font-size: .78rem; color: var(--as-muted); }
332: .as-hints span { display: inline-flex; align-items: center; gap: .35rem; }
333: 
334: .as-jump { position: absolute; inset-inline-start: 50%; translate: 50% 0; bottom: calc(var(--as-composer-h, 120px) + 12px); z-index: 3; display: inline-flex; align-items: center; gap: .35rem; padding: .35rem .8rem; border-radius: 99px; background: var(--as-surface); border: 1px solid var(--as-border); box-shadow: var(--as-shadow); font-size: .78rem; color: var(--as-muted); white-space: nowrap; }
335: 
336: /* ---------- Alerts ---------- */
337: .as-alert { display: flex; align-items: flex-start; gap: .65rem; padding: .7rem .85rem; border-radius: var(--as-radius-sm); border: 1px solid; font-size: .87rem; line-height: 1.6; }
338: .as-alert .as-icon { margin-top: 2px; }
339: .as-alert-body { flex: 1; min-width: 0; display: grid; gap: .1rem; }
340: .as-alert-body strong { font-weight: 600; }
341: .as-alert-actions { display: flex; gap: .25rem; align-items: center; flex-wrap: wrap; }
342: .as-alert--danger { background: var(--as-danger-soft); border-color: color-mix(in oklab, var(--as-danger) 35%, transparent); color: var(--as-danger); }
343: .as-alert--warning { background: var(--as-warning-soft); border-color: color-mix(in oklab, var(--as-warning) 35%, transparent); color: var(--as-warning); }
344: .as-alert--info { background: var(--as-info-soft); border-color: color-mix(in oklab, var(--as-info) 30%, transparent); color: var(--as-info); }
345: .as-alert--success { background: var(--as-success-soft); border-color: color-mix(in oklab, var(--as-success) 30%, transparent); color: var(--as-success); }
346: .as-alert .as-alert-body span { color: var(--as-text); opacity: .85; }
347: .as-error-dock { width: 100%; max-width: 820px; margin-inline: auto; padding: 0 1.25rem .5rem; }
348: 
349: /* ---------- Composer ---------- */
350: .as-composer-wrap { width: 100%; max-width: 820px; margin-inline: auto; padding: .25rem 1.25rem 1rem; }
351: .as-composer { position: relative; }
352: .as-composer-box { position: relative; display: grid; gap: .35rem; padding: .55rem .55rem .5rem; border-radius: 18px; background: var(--as-surface); border: 1px solid var(--as-border); box-shadow: var(--as-shadow); transition: border-color .15s, box-shadow .15s; }
353: .as-composer-box:focus-within { border-color: var(--as-primary-ring); box-shadow: var(--as-shadow), 0 0 0 4px var(--as-primary-soft); }
354: .as-composer[data-disabled='true'] .as-composer-box { background: var(--as-surface-2); box-shadow: none; }
355: .as-composer textarea { width: 100%; min-height: 44px; max-height: 200px; padding: .45rem .55rem; border: 0; outline: 0; resize: none; background: transparent; line-height: 1.6; color: var(--as-text); }
356: .as-composer textarea:focus-visible { outline: none; }
357: .as-composer textarea::placeholder { color: var(--as-faint); }
358: .as-composer textarea:disabled { cursor: not-allowed; }
359: .as-composer-foot { display: flex; align-items: center; gap: .35rem; }
360: .as-trigger { display: inline-grid; place-items: center; min-width: 30px; height: 30px; padding: 0 .35rem; border-radius: 8px; font-family: var(--as-mono); font-size: .9rem; font-weight: 500; color: var(--as-muted); transition: background .12s, color .12s; }
361: .as-trigger:hover:not(:disabled) { background: var(--as-surface-2); color: var(--as-primary); }
362: .as-counter { white-space: nowrap; margin-inline-start: auto; font-size: .72rem; color: var(--as-faint); }
363: .as-counter[data-near='true'] { color: var(--as-warning); font-weight: 600; }
364: .as-send { width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: var(--as-primary); color: #fff; transition: background .15s, transform .1s, opacity .15s; }
365: .as-send:hover:not(:disabled) { background: var(--as-primary-hover); }
366: .as-send:disabled { background: var(--as-surface-3); color: var(--as-faint); }
367: .as-send[data-busy='true'] { background: var(--as-primary-soft); color: var(--as-primary); }
368: .as-spin { width: 16px; height: 16px; border-radius: 50%; border: 2px solid currentColor; border-top-color: transparent; animation: as-rot .7s linear infinite; }
369: @keyframes as-rot { to { rotate: 360deg; } }
370: .as-composer-note { display: flex; justify-content: center; gap: .4rem; margin-top: .45rem; font-size: .72rem; color: var(--as-faint); text-align: center; }
371: .as-tags { display: flex; flex-wrap: wrap; gap: .35rem; padding: .1rem .2rem 0; }
372: .as-tag { display: inline-flex; align-items: center; gap: .3rem; height: 28px; padding-inline: .5rem .25rem; border-radius: 8px; font-size: .8rem; font-weight: 500; background: var(--as-surface-2); border: 1px solid var(--as-border); animation: as-in .18s ease both; }
373: .as-tag[data-entity='user'] { color: var(--as-info); background: var(--as-info-soft); border-color: transparent; }
374: .as-tag[data-entity='branch'] { color: var(--as-success); background: var(--as-success-soft); border-color: transparent; }
375: .as-tag[data-entity='role'] { color: var(--as-primary); background: var(--as-primary-soft); border-color: transparent; }
376: .as-tag button { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 5px; color: inherit; opacity: .7; }
377: .as-tag button:hover:not(:disabled) { opacity: 1; background: #0000000f; }
378: .as-tag--static { padding-inline: .5rem; height: 24px; font-size: .75rem; }
379: 
380: /* Mention popover */
381: .as-pop { position: absolute; inset-inline: 0; bottom: calc(100% + 8px); z-index: 10; max-height: min(320px, 50vh); display: flex; flex-direction: column; border-radius: var(--as-radius); background: var(--as-surface); border: 1px solid var(--as-border); box-shadow: var(--as-shadow-lg); overflow: hidden; animation: as-pop .16s ease both; }
382: @keyframes as-pop { from { opacity: 0; translate: 0 6px; scale: .985; } }
383: .as-pop-head { display: flex; align-items: center; gap: .5rem; padding: .55rem .8rem; font-size: .75rem; color: var(--as-muted); border-bottom: 1px solid var(--as-border); background: var(--as-surface-2); }
384: .as-pop-head strong { color: var(--as-text); font-weight: 600; }
385: .as-pop-head .as-kbdrow { margin-inline-start: auto; display: flex; gap: .3rem; align-items: center; }
386: .as-pop-list { overflow-y: auto; overflow-x: hidden; padding: .3rem; list-style: none; margin: 0; }
387: .as-opt { display: flex; align-items: center; gap: .65rem; width: 100%; padding: .5rem .6rem; border-radius: var(--as-radius-xs); text-align: start; }
388: .as-opt[aria-selected='true'] { background: var(--as-primary-soft); }
389: .as-opt[aria-selected='true'] .as-opt-label { color: var(--as-primary); }
390: .as-opt:disabled { opacity: .45; }
391: .as-opt-ic { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; background: var(--as-surface-2); color: var(--as-muted); flex: none; }
392: .as-opt-txt { flex: 1; min-width: 0; display: grid; }
393: .as-opt-label { font-size: .88rem; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
394: .as-opt-label mark { background: none; color: var(--as-primary); font-weight: 700; }
395: .as-opt-meta { font-size: .74rem; color: var(--as-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
396: .as-opt-enter { margin-inline-start: auto; opacity: 0; }
397: .as-opt[aria-selected='true'] .as-opt-enter { opacity: 1; }
398: .as-pop-empty { padding: 1.4rem 1rem; text-align: center; color: var(--as-muted); font-size: .84rem; display: grid; gap: .25rem; justify-items: center; }
399: .as-pop-empty .as-icon { color: var(--as-faint); }
400: .as-pop-loading { display: grid; gap: .3rem; padding: .4rem; }
401: .as-pop-loading i { display: block; height: 38px; border-radius: var(--as-radius-xs); background: linear-gradient(90deg, var(--as-surface-2) 30%, var(--as-surface-3) 50%, var(--as-surface-2) 70%); background-size: 300% 100%; animation: as-shimmer 1.4s infinite linear; }
402: 
403: /* ---------- Action blocks ---------- */
404: .as-block { width: 100%; max-width: 640px; border-radius: var(--as-radius); background: var(--as-surface); border: 1px solid var(--as-border); box-shadow: var(--as-shadow-sm); overflow: hidden; }
405: .as-block-head { display: flex; align-items: flex-start; gap: .7rem; padding: .9rem 1rem .75rem; }
406: .as-block-ic { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; flex: none; background: var(--as-primary-soft); color: var(--as-primary); }
407: .as-block-title { flex: 1; min-width: 0; display: grid; gap: .1rem; }
408: .as-block-title h3 { font-size: .95rem; font-weight: 600; line-height: 1.45; }
409: .as-block-title span { font-size: .76rem; color: var(--as-muted); }
410: .as-block-body { padding: 0 1rem 1rem; display: grid; gap: .8rem; }
411: .as-block-foot { display: flex; align-items: center; gap: .5rem; flex-wrap: wrap; padding: .7rem 1rem; border-top: 1px solid var(--as-border); background: var(--as-surface-2); }
412: .as-block-foot .as-spacer { flex: 1; }
413: .as-block[data-state='expired'] { border-style: dashed; }
414: .as-block[data-state='expired'] .as-block-body, .as-block[data-state='expired'] .as-block-head { opacity: .6; }
415: .as-block[data-state='expired'] .as-block-ic { background: var(--as-surface-2); color: var(--as-faint); }
416: .as-block[data-state='executed'] .as-block-ic { background: var(--as-success-soft); color: var(--as-success); }
417: .as-block[data-state='cancelled'] .as-block-ic, .as-block[data-state='undone'] .as-block-ic { background: var(--as-surface-2); color: var(--as-muted); }
418: .as-block[data-state='failed'] .as-block-ic { background: var(--as-danger-soft); color: var(--as-danger); }
419: .as-block[data-sensitive='true'] { border-color: color-mix(in oklab, var(--as-warning) 40%, var(--as-border)); }
420: .as-block[data-sensitive='true'] .as-block-ic { background: var(--as-warning-soft); color: var(--as-warning); }
421: 
422: .as-timer { display: inline-flex; align-items: center; gap: .4rem; padding: .2rem .55rem .2rem .3rem; border-radius: 99px; font-size: .78rem; font-weight: 600; color: var(--as-muted); background: var(--as-surface-2); border: 1px solid var(--as-border); white-space: nowrap; }
423: .as-timer[data-level='warn'] { color: var(--as-warning); background: var(--as-warning-soft); border-color: transparent; }
424: .as-timer[data-level='crit'] { color: var(--as-danger); background: var(--as-danger-soft); border-color: transparent; animation: as-pulse 1s infinite; }
425: .as-badge { display: inline-flex; align-items: center; gap: .3rem; padding: .15rem .55rem; border-radius: 99px; font-size: .74rem; font-weight: 600; white-space: nowrap; background: var(--as-surface-2); color: var(--as-muted); }
426: .as-badge--success { background: var(--as-success-soft); color: var(--as-success); }
427: .as-badge--danger { background: var(--as-danger-soft); color: var(--as-danger); }
428: .as-badge--warning { background: var(--as-warning-soft); color: var(--as-warning); }
429: .as-badge--info { background: var(--as-info-soft); color: var(--as-info); }
430: 
431: /* Diff (before/after) */
432: .as-diff { border: 1px solid var(--as-border); border-radius: var(--as-radius-sm); overflow: hidden; }
433: .as-diff-head, .as-diff-row { display: grid; grid-template-columns: minmax(6.5rem, .7fr) 1fr 1fr; }
434: .as-diff-head { font-size: .72rem; font-weight: 600; color: var(--as-muted); background: var(--as-surface-2); }
