352:   const groups = useMemo(() => {
353:     const g: Record<string, Conv[]> = {};
354:     for (const c of conversations) {
355:       const k = c.is_pinned ? 'pinned' : dayKey(c.last_message_at);
356:       (g[k] ??= []).push(c);
357:     }
358:     return ['pinned', 'today', 'yesterday', 'week', 'older'].filter(k => g[k]?.length).map(k => ({ key: k, items: g[k] }));
359:   }, [conversations]);
360: 
361:   const pendingCount = (c: Conv) => (c.pending_actions ?? []).filter(a => a.status === 'pending').length;
362:   const elapsed = streaming ? Math.floor((Date.now() - startedAt) / 1000) : 0;
363:   const totalTokens = conversations.reduce((s, c) => s + (c.total_tokens || 0), 0);
