409:                           <span className="as-conv-title">{c.title ?? `محادثة ${c.id}`}</span>
410:                           <span className="as-conv-meta">
411:                             {relTime(c.last_message_at) || 'جديدة'}
412:                             {pc > 0 && <><span className="as-dot" />{pc} بانتظار التأكيد</>}
413:                           </span>
414:                         </button>
415:                         <div className="as-conv-actions">
