417:                           <button type="button" className="as-iconbtn as-iconbtn--sm" disabled={busy} aria-label="حذف المحادثة" title="حذف" onClick={() => setConfirmDelete(c.id)}><Icon name="trash" size={15} /></button>
418:                         </div>
419:                       </>
420:                     )}
421:                   </div>
422:                 );
423:               })}
424:             </div>
425:           ))
426:         ) : debouncedQuery ? (
427:           <div className="as-list-empty">
428:             <span className="as-empty-icon"><Icon name="search" size={20} /></span>
429:             <strong>مفيش نتائج لـ «{debouncedQuery}»</strong>
430:             <span>جرّب كلمة تانية أو امسح البحث.</span>
431:             <button type="button" className="as-btn as-btn--sm" onClick={() => setSearchQuery('')}>مسح البحث</button>
432:           </div>
