443:         <span className="as-num">{totalTokens.toLocaleString('ar-EG')} توكن</span>
444:         <button type="button" className="as-btn as-btn--ghost as-btn--sm" style={{ marginInlineStart: 'auto' }} onClick={() => { setTab('admin'); setDrawer(false); }}>التفاصيل</button>
445:       </div>
446:     </aside>
