 75: #root { min-height: 100vh; background: var(--bg-canvas); color: var(--text-primary); transition: background-color .3s; }
 76: 
 77: .v-card { background: var(--bg-card); border-radius: 22px; border: 1px solid var(--border-subtle); }
 78: .v-subcard { background: var(--bg-subcard); border-radius: 16px; }
 79: .v-pill { background: var(--bg-card); border: 1px solid var(--border-subtle); }
 80: .v-divide > * + * { border-top: 1px solid var(--divider-color); }
 81: .v-border-b { border-bottom: 1px solid var(--divider-color); }
 82: .v-border-t { border-top: 1px solid var(--divider-color); }
 83: .v-well { background: var(--icon-well-bg); color: var(--text-secondary); }
 84: .t-1 { color: var(--text-primary); } .t-2 { color: var(--text-secondary); } .t-3 { color: var(--text-muted); }
 85: .t-acc { color: var(--accent); }
 86: .bg-acc { background: var(--accent); color: #fff; }
 87: .bg-ink { background: var(--pill-active-bg); color: var(--pill-active-text); }
 88: 
 89: .v-orange { background: radial-gradient(circle at 22% 18%, #f4886b 0%, #e6542b 55%, #db4218 100%); color: #fff; }
 90: .hatched-acc { background: repeating-linear-gradient(-45deg, var(--accent) 0, var(--accent) 2.5px, var(--accent-2) 2.5px, var(--accent-2) 5px); }
 91: .hatched-track { background: var(--hatched-track); }
 92: 
 93: .b-green { background: var(--badge-green-bg); color: var(--badge-green-text); }
 94: .b-red { background: var(--badge-red-bg); color: var(--badge-red-text); }
 95: .b-amber { background: var(--badge-amber-bg); color: var(--badge-amber-text); }
 96: .b-blue { background: var(--badge-blue-bg); color: var(--badge-blue-text); }
 97: .b-gray { background: var(--icon-well-bg); color: var(--text-secondary); }
 98: .b-acc { background: var(--accent-light); color: var(--accent); }
