 341:   return (
 342:     <div className="space-y-5">
 343:       {p.status === 'published' && <Banner tone="amber">المنتج منشور: أي تعديل لازم يحافظ على شروط النشر</Banner>}
 344:       <PageHeader crumbs={[{ label: 'الكتالوج' }, { label: 'المنتجات', href: '#/products' }, { label: isNew && !p.code ? 'منتج جديد' : (B.ar || p.code) }]}
 345:         title={isNew && !p.code ? 'منتج جديد' : B.ar || 'بدون اسم'}
 346:         badge={<>{p.status ? <StatusBadge s={p.status} /> : <Badge>لم يُحفظ بعد</Badge>}{p.code && <span className="ltr text-[12px] font-semibold px-2.5 py-1 rounded-full v-pill t-2">{p.code}</span>}</>}
 347:         actions={<button className="btn btn-soft" onClick={() => dirty ? setLeave(true) : nav('/products')}><Icon name="arrowRight" size={14} />المنتجات</button>} />
 348: 
 349:       <div className="flex flex-wrap items-center justify-between gap-3 stagger s2">
 350:         <Tabs value={tab.tab} onChange={(t) => setTabQ({ tab: t })} tabs={tabs} />
 351:         <div className="flex items-center gap-3 v-pill rounded-full ps-4 pe-1.5 h-11">
 352:           <span className="text-[12px] t-2">الجاهزية للنشر</span>
 353:           <div className="w-24 h-2 rounded-full hatched-track overflow-hidden"><div className="h-full rounded-full hatched-acc transition-all" style={{ width: `${(readyCount / ready.length) * 100}%` }} /></div>
 354:           <span className={cx('h-8 px-3 rounded-full text-[12px] font-bold num flex items-center', readyCount === ready.length ? 'b-green' : 'v-well t-1')}>{readyCount}/{ready.length}</span>
 355:         </div>
 356:       </div>
 357: 
 358:       {summary && <ErrorSummary title={summary.title} subtitle={summary.subtitle} items={summary.items} onClose={() => setSummary(null)} onJump={(it) => setTabQ({ tab: it.go })} />}
 359: 
 360:       <fieldset disabled={!writable || (!!flow && !flow.done)} className="stagger s3">
 361:         {tab.tab === 'basic' && <BasicTab B={B} set={setBasic} errs={errs.basic} code={p.code} flat={flat} />}
 362:         {tab.tab === 'variants' && (
 363:           <VariantsTab channel={B.channel} canCost={canCost} mode={p.mode}
 364:             setMode={(m) => setP({ ...p, mode: m, rows: m === 'single' ? [p.rows[0] || emptyVariant(null, '', '', 0)].map((r) => ({ ...r, color: null, size: '', capacity: '' })) : p.rows })}
 365:             axes={p.axes} setAxes={(a) => setP({ ...p, axes: a })} rows={p.rows}
 366:             setRows={(rows) => {
 367:               const nowActive = rows.filter((r) => r.status === 'active').length;
 368:               if (p.status === 'published' && nowActive === 0) { setBlockModal('last'); return; }
 369:               const removedPrice = p.status === 'published' && rows.some((r) => r.status === 'active' && ((needRetail && !r.retail) || (needWh && !r.wholesale))) && missingPrice.length === 0;
 370:               if (removedPrice) { setBlockModal('price'); return; }
 371:               const ids=new Set(rows.map(r=>r.serverId));const byVariant=Object.fromEntries(Object.entries(p.media.byVariant).map(([color,items])=>[color,items.filter(file=>!file.variantId||ids.has(file.variantId))]));
 372:               setP({ ...p, rows,media:{...p.media,byVariant} });
 373:             }}
 374:             errs={errs.variantsShown ? {...vErrs,...errs.variants} : {}} />
 375:         )}
 376:         {tab.tab === 'media' && <MediaTab media={p.media} setMedia={(m) => setP({ ...p, media: m })} axes={p.axes} mode={p.mode} saved={!!p.status} onRetry={()=>run(false)} />}
 377:         {tab.tab === 'review' && <ReviewTab p={p} ready={ready} canCost={canCost} canPublish={canPublish} goto={(t) => setTabQ({ tab: t })} catNode={catNode} />}
 378:       </fieldset>
 379: 
 380:       {writable && <StickyBar dirty={dirty} note={p.status ? null : 'الصور هتترفع بعد حفظ المسودة'}>
 381:         {tab.tab !== 'review' && <button className="btn btn-ghost" onClick={() => setTabQ({ tab: tabs[Math.min(3, tabs.findIndex((t) => t.value === tab.tab) + 1)].value })}>التالي<Icon name="chevLeft" size={14} /></button>}
 382:         <button className="btn btn-outline" onClick={() => run(false)} disabled={!writable || (!!flow && !flow.done)}><Icon name="edit" size={14} />{p.status === 'published'||p.status==='archived' ? 'حفظ التعديلات' : 'حفظ كمسودة'}</button>
 383:         {canPublish && p.id && (p.status==='published'?[['draft','إلغاء النشر'],['archived','أرشفة']]:p.status==='archived'?[['draft','استرجاع كمسودة']]:[]).map(([status,label])=><button key={status} disabled={!!flow&&!flow.done} className="btn btn-soft" onClick={async()=>{if(dirty&&!window.confirm('تغيير الحالة سيحفظ حالة المنتج فقط. ستبقى تعديلاتك غير المحفوظة؛ متابعة؟'))return;try{await productsApi.update(p.id,{status});setP({...p,status});setSaved(JSON.stringify({...JSON.parse(saved),status}));}catch(e){vtoast(normalizeError(e).message,'error');}}}>{label}</button>)}
 384:         {canPublish ? (
 385:           p.status !== 'published' && writable && <button className="btn btn-acc" onClick={() => {
 386:             if (readyCount < ready.length) { setSummary({ title: 'المنتج غير جاهز للنشر', subtitle: 'أكمل البنود التالية، أو احفظه كمسودة لحين الانتهاء.', items: ready.filter((r) => !r.ok && r.tab).map((r) => ({ text: `${r.label} — ${r.detail}`, tab: tabs.find((t) => t.value === r.tab).label, go: r.tab })) }); return; }
 387:             run(true);
 388:           }} disabled={!!flow && !flow.done}><Icon name="send" size={14} />{p.status==='archived'?'إعادة النشر':'حفظ ونشر'}</button>
 389:         ) : <span className="h-10 px-4 rounded-full v-well text-[12px] font-medium flex items-center gap-1.5" title="يتطلب products.publish"><Icon name="lock" size={13} />النشر يتطلب صلاحية</span>}
 390:       </StickyBar>}
 391: 
 392:       <PublishFlow flow={flow} onClose={() => setFlow(null)} onRetryUpload={() => { setP({ ...p, media: { ...p.media, general: p.media.general.map((f) => f.status === 'failed' ? { ...f, status: 'queued', progress: 0, error: null } : f) } }); setFlow(null); setTabQ({ tab: 'media' }); }}
 393:         onGoto={(t) => { setFlow(null); setTabQ({ tab: t }); }} />
 394:       <Modal open={!!blockModal} onClose={() => setBlockModal(null)} icon="ban" iconTone="red"
 395:         title={blockModal === 'last' ? 'لا يمكن تعطيل آخر متغير نشط' : 'لا يمكن إزالة سعر مطلوب'}
 396:         subtitle={blockModal === 'last' ? 'المنتج منشور حاليًا، والمنتج المنشور لازم يكون فيه متغير نشط واحد على الأقل.' : `المنتج منشور على قناة «${CHANNEL_LABEL[B.channel]}»، والسعر ده مطلوب لكل متغير نشط. الخادم هيرفض الحفظ.`}>
 397:         <div className="v-subcard p-4 text-[12.5px] t-2 leading-relaxed">
 398:           {canPublish ? 'لو محتاج توقف بيع المنتج مؤقتًا، حوّله لمسودة الأول — هيختفي من المتجر ونقاط البيع، وبعدها تقدر تعدل بحرية.' : 'تحويل المنتج لمسودة يتطلب صلاحية النشر. تواصل مع مسؤول الكتالوج.'}
 399:         </div>
 400:         <div className="flex justify-end gap-2 mt-5">
 401:           <button className="btn btn-soft" onClick={() => setBlockModal(null)}>تراجع عن التغيير</button>
 402:           {canPublish && <button className="btn btn-ink" onClick={() => { productsApi.update(p.id,{status:'draft'}).then(()=>{setP({...p,status:'draft'});setBlockModal(null);}).catch(e=>vtoast(normalizeError(e).message,'error')); }}>تحويل لمسودة</button>}
 403:         </div>
 404:       </Modal>
 405:       <LeaveDialog open={leave} onStay={() => setLeave(false)} onLeave={() => { setLeave(false); nav('/products'); }} />
 406:     </div>
 407:   );
 408: }
