 419:             <Field label="اسم المنتج (إنجليزي)" required error={errs.en} hint={B.en && !/[a-z]/i.test(B.en) ? 'يُفضّل كتابة الاسم بالإنجليزية لتوليد رابط مناسب' : null} id="en"><Input ltr dir="ltr" value={B.en} onChange={(e) => set('en', e.target.value)} error={errs.en} placeholder="Alfarid Travel Bag" /></Field>
 420:             <Field label="القسم" required error={errs.category}>
 421:               <SearchSelect value={B.category} onChange={(v) => set('category', v)} error={errs.category} placeholder="اختر القسم" emptyText="لا يوجد قسم بهذا الاسم"
 422:                 options={flat.map((f) => ({ value: f.id, label: f.ar, depth: f.depth, sub: f.depth ? null : f.en, note: f.status !== 'active' ? 'غير نشط' : null }))} />
 423:             </Field>
 424:           </div>
 425:           <div className="mt-5">
 426:             <Field label="قناة البيع" required error={errs.channel} hint="بتحدد الأسعار المطلوبة لكل متغير قبل النشر.">
 427:               <div className="grid grid-cols-3 gap-2.5">
 428:                 {[['retail', 'تجزئة', 'سعر التجزئة مطلوب', 'cart'], ['wholesale', 'جملة', 'سعر الجملة مطلوب', 'warehouse'], ['both', 'الاتنين', 'السعرين مطلوبين', 'layers']].map(([k, l, s, ic]) => (
 429:                   <button key={k} type="button" onClick={() => set('channel', k)} className={cx('rounded-[16px] p-3.5 text-start border transition', B.channel === k ? 'border-[var(--accent)] bg-[var(--accent-soft)]' : 'border-[var(--border-field)] hover:bg-[var(--bg-subcard)]')}>
 430:                     <span className={cx('w-8 h-8 rounded-full flex items-center justify-center mb-2', B.channel === k ? 'bg-acc' : 'v-well')}><Icon name={ic} size={15} /></span>
 431:                     <span className="block text-[13px] font-semibold t-1">{l}</span><span className="block text-[11px] t-3">{s}</span>
 432:                   </button>
 433:                 ))}
 434:               </div>
 435:             </Field>
 436:           </div>
 437:         </SectionCard>
 438: 
 439:         <SectionCard title="الوصف والخامة" aside={<Seg value={descLang} onChange={setDescLang} options={[{ value: 'ar', label: 'عربي' }, { value: 'en', label: 'English' }]} />}>
 440:           <div className="space-y-4">
 441:             {descLang === 'ar' ? <>
 442:               <Field label="الوصف"><Textarea rows={4} value={B.desc_ar} onChange={(e) => set('desc_ar', e.target.value)} /></Field>
 443:               <Field label="الخامة"><Input value={B.mat_ar} onChange={(e) => set('mat_ar', e.target.value)} placeholder="مثال: بوليستر مقاوم للماء" /></Field>
 444:             </> : <>
 445:               <Field label="Description"><Textarea rows={4} dir="ltr" className="ltr" value={B.desc_en} onChange={(e) => set('desc_en', e.target.value)} /></Field>
 446:               <Field label="Material"><Input ltr value={B.mat_en} onChange={(e) => set('mat_en', e.target.value)} /></Field>
 447:             </>}
 448:           </div>
 449:         </SectionCard>
 450: 
 451:         <SectionCard title="الأبعاد والضمان">
 452:           <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
 453:             <Field label="الطول"><Input ltr suffix="سم" value={B.l} onChange={(e) => set('l', e.target.value)} /></Field>
 454:             <Field label="العرض"><Input ltr suffix="سم" value={B.w} onChange={(e) => set('w', e.target.value)} /></Field>
 455:             <Field label="الارتفاع"><Input ltr suffix="سم" value={B.h} onChange={(e) => set('h', e.target.value)} /></Field>
 456:             <Field label="الوزن"><Input ltr suffix="كجم" value={B.kg} onChange={(e) => set('kg', e.target.value)} /></Field>
 457:           </div>
