 720: function useUnsavedGuard(dirty) {
 721:   useEffect(() => {
 722:     const h = (e) => { if (dirty) { e.preventDefault(); e.returnValue = ''; } };
 723:     window.addEventListener('beforeunload', h);
 724:     return () => window.removeEventListener('beforeunload', h);
 725:   }, [dirty]);
 726: }
