 739: /* ---------------- Toasts ---------------- */
 740: function vtoast(text, kind = 'success') {
 741:   window.dispatchEvent(new CustomEvent('vtoast', { detail: { text, kind, id: Math.random() } }));
 742: }
 743: function ToastHost() {
 744:   const [items, setItems] = useState([]);
 745:   useEffect(() => {
 746:     const h = (e) => {
 747:       const t = e.detail;
 748:       setItems((x) => [...x, t]);
 749:       setTimeout(() => setItems((x) => x.filter((i) => i.id !== t.id)), 2800);
 750:     };
 751:     window.addEventListener('vtoast', h);
 752:     return () => window.removeEventListener('vtoast', h);
 753:   }, []);
 754:   return (
 755:     <div className="fixed bottom-6 left-6 z-[80] flex flex-col gap-2 items-start pointer-events-none">
 756:       {items.map((t) => (
 757:         <div key={t.id} className="pop px-4 py-2.5 rounded-full shadow-lg text-[12.5px] font-medium flex items-center gap-2 bg-ink">
 758:           <span className={cx('w-2 h-2 rounded-full', t.kind === 'error' ? 'bg-rose-500' : t.kind === 'info' ? 'bg-sky-400' : 'bg-[var(--accent)]')} />
 759:           {t.text}
 760:         </div>
 761:       ))}
 762:     </div>
 763:   );
 764: }
