 844: /* ---------------- Popover helper ---------------- */
 845: function useOutside(ref, cb, active) {
 846:   useEffect(() => {
 847:     if (!active) return;
 848:     const h = (e) => { if (ref.current && !e.composedPath().includes(ref.current)) cb(); };
 849:     document.addEventListener('mousedown', h);
 850:     return () => document.removeEventListener('mousedown', h);
 851:   }, [active]);
 852: }
