 943: /* ---------------- Modal / Confirm ---------------- */
 944: function Modal({ open, onClose, children, width = 460, title, subtitle, icon, iconTone = 'acc', footer }) {
 945:   useEffect(() => {
 946:     if (!open) return;
 947:     const h = (e) => e.key === 'Escape' && onClose && onClose();
 948:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
 949:   }, [open]);
 950:   if (!open) return null;
 951:   return (
 952:     <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 fade" style={{ background: 'var(--overlay)', backdropFilter: 'blur(3px)' }} onMouseDown={(e) => e.target === e.currentTarget && onClose && onClose()}>
 953:       <div className="pop v-card w-full overflow-hidden" style={{ maxWidth: width, boxShadow: 'var(--shadow-pop)', borderRadius: 26 }}>
 954:         {(title || icon) && (
 955:           <div className="p-6 pb-0 flex items-start gap-3.5">
 956:             {icon && <span className={cx('w-11 h-11 rounded-full flex items-center justify-center shrink-0', 'b-' + iconTone)}><Icon name={icon} size={19} /></span>}
 957:             <div className="flex-1 min-w-0 pt-0.5">
 958:               <h3 className="font-display text-[17px] font-semibold t-1">{title}</h3>
 959:               {subtitle && <p className="text-[13px] t-2 mt-1 leading-relaxed text-pretty">{subtitle}</p>}
 960:             </div>
 961:             {onClose && <button className="icon-btn -mt-1 -me-1" onClick={onClose}><Icon name="x" size={16} /></button>}
 962:           </div>
 963:         )}
 964:         <div className="p-6">{children}</div>
 965:         {footer && <div className="px-6 pb-6 -mt-2 flex items-center justify-end gap-2">{footer}</div>}
 966:       </div>
 967:     </div>
 968:   );
 969: }
