1423: 
1424:   const generate = () => {
1425:     const cs = axes.colors.length ? axes.colors : [null];
1426:     const ss = axes.sizes.length ? axes.sizes : [''];
1427:     const ps = axes.capacities.length ? axes.capacities : [''];
1428:     const existing = Object.fromEntries(rows.map((r) => [vKey(r.color, r.size, r.capacity), r]));
1429:     const next = []; let kept = 0, added = 0;
1430:     cs.forEach((c) => ss.forEach((s) => ps.forEach((p) => {
1431:       const k = vKey(c, s, p);
1432:       if (existing[k]) { next.push({ ...existing[k], color: c }); kept++; } else { next.push(emptyVariant(c, s, p, next.length)); added++; }
1433:     })));
1434:     const removed = rows.length - kept;
1435:     setRows(next.slice(0, 100)); setSel([]);
1436:     setGenNote({ kept, added, removed, capped: next.length > 100 });
1437:   };
1438:   const upd = (id, patch) => setRows(rows.map((r) => r._id === id ? { ...r, ...patch } : r));
1439:   const copyDown = (k) => {
