1443:     vtoast(`تم نسخ ${src[k]} ${sel.length ? 'للصفوف المحددة' : 'لكل الصفوف'}`);
1444:   };
1445:   const applyBulk = () => {
1446:     if (!bulk.value || !priceOk(bulk.value,bulk.field==='cost'?4:2)) { vtoast(bulk.field==='cost'?'أدخل تكلفة صالحة (أربع خانات عشرية)':'أدخل سعر صالح (منزلتين عشريتين)', 'error'); return; }
1447:     setRows(rows.map((r) => sel.includes(r._id) ? { ...r, [bulk.field]: bulk.value } : r));
