1452:     if (e.key === 'ArrowDown' || (e.key === 'Enter' && !e.shiftKey)) move(1, 0);
1453:     if (e.key === 'ArrowUp' || (e.key === 'Enter' && e.shiftKey)) move(-1, 0);
1454:     if (e.key === 'ArrowLeft' && e.target.selectionStart === e.target.value.length) move(0, 1);
