 16: export function ToastHost() {
 17:   const [items, setItems] = useState([]);
 18:   useEffect(() => {
 19:     const h = (e) => {
 20:       const t = e.detail;
 21:       setItems((x) => [...x, t]);
 22:       setTimeout(() => setItems((x) => x.filter((i) => i.id !== t.id)), 2800);
 23:     };
 24:     window.addEventListener('vtoast', h);
 25:     return () => window.removeEventListener('vtoast', h);
 26:   }, []);
 27:   return (
 28:     <div className="fixed bottom-6 left-6 z-[80] flex flex-col gap-2 items-start pointer-events-none">
 29:       {items.map((t) => (
 30:         <div key={t.id} className="pop px-4 py-2.5 rounded-full shadow-lg text-[12.5px] font-medium flex items-center gap-2 bg-ink">
 31:           <span className={cx('w-2 h-2 rounded-full', t.kind === 'error' ? 'bg-rose-500' : t.kind === 'info' ? 'bg-sky-400' : 'bg-[var(--accent)]')} />
 32:           {t.text}
 33:         </div>
 34:       ))}
 35:     </div>
 36:   );
